238	fn extract_from_checkpoint(session_id: &str) -> Option<PathBuf> {
239	    let conn = crate::db::connect().ok()?;
240	    let jsonl_path: String = conn.query_row(
241	        "SELECT jsonl_path FROM checkpoints
242	         WHERE session_id = ?1
243	           AND jsonl_path IS NOT NULL
244	         ORDER BY checkpoint_number DESC
245	         LIMIT 1",
246	        [session_id],
247	        |row| row.get(0),
248	    ).ok()?;
249	
250	    // The stored `repo_dir` is whichever repo's index pass last wrote this
251	    // checkpoint row — sometimes stale (the file may since have been removed
252	    // from that repo's branch, or the same file lives in multiple repos'
253	    // shared checkpoint branch). Try the recorded repo_dir first, then fall
254	    // back to every other tracked repo. Whichever clone actually has the path
255	    // in its checkpoint branch wins.
256	    let preferred: Option<String> = conn.query_row(
257	        "SELECT repo_dir FROM checkpoints
258	         WHERE session_id = ?1 AND repo_dir IS NOT NULL
259	         ORDER BY checkpoint_number DESC LIMIT 1",
260	        [session_id], |row| row.get(0),
261	    ).ok();
262	
263	    let mut candidates: Vec<String> = Vec::new();
264	    if let Some(p) = preferred { candidates.push(p); }
265	    if let Ok(mut stmt) = conn.prepare("SELECT directory FROM repositories") {
266	        if let Ok(rows) = stmt.query_map([], |row| row.get::<_, String>(0)) {
267	            for r in rows.flatten() {
268	                if !candidates.contains(&r) { candidates.push(r); }
269	            }
270	        }
271	    }
272	
273	    let bytes = candidates.iter()
274	        .find_map(|dir| crate::commands::index::git_show(dir, &jsonl_path).ok())?;
275	
276	    let home = std::env::var("HOME").ok()?;
277	    let cache_dir = PathBuf::from(&home).join(".gossamer").join("sessions");
278	    std::fs::create_dir_all(&cache_dir).ok()?;
279	    let cache_path = cache_dir.join(format!("{session_id}.jsonl"));
280	    std::fs::write(&cache_path, &bytes).ok()?;
281	    Some(cache_path)
282	}
