286	fn parse(raw: &str, agent: &str) -> Vec<Card> {
287	    let mut tool_names: HashMap<String, String> = HashMap::new();
288	    for line in raw.lines() {
289	        if let Ok(v) = serde_json::from_str::<Value>(line) {
290	            if let Some(blocks) = v["message"]["content"].as_array() {
291	                for b in blocks {
292	                    if b["type"].as_str() == Some("tool_use") {
293	                        if let (Some(id), Some(name)) = (b["id"].as_str(), b["name"].as_str()) {
294	                            tool_names.insert(id.to_string(), name.to_string());
295	                        }
296	                    }
297	                }
298	            }
299	        }
300	    }
301	
302	    let mut cards: Vec<Card> = Vec::new();
303	    let mut first_cwd    = String::new();
304	    let mut first_branch = String::new();
305	    let mut first_ts     = String::new();
306	    let mut title: Option<String> = None;
307	
308	    for line in raw.lines() {
309	        if line.trim().is_empty() { continue; }
310	        let Ok(v) = serde_json::from_str::<Value>(line) else { continue };
311	        let ts = v["timestamp"].as_str().unwrap_or("").to_string();
312	        if first_ts.is_empty() && !ts.is_empty() { first_ts = ts.clone(); }
313	
314	        match v["type"].as_str() {
315	            Some("custom-title") => {
316	                title = v["customTitle"].as_str().map(str::to_string);
317	            }
318	            Some("system") => {
319	                if let Some(c) = v["cwd"].as_str() { if first_cwd.is_empty() { first_cwd = c.to_string(); } }
320	                let content = v["content"].as_str().unwrap_or("").to_string();
321	                if !content.is_empty() {
322	                    let subtype = v["subtype"].as_str().unwrap_or("system").replace('_', " ");
323	                    cards.push(Card::System { ts, subtype, content });
324	                }
325	            }
326	            Some("user") => {
327	                if let Some(c) = v["cwd"].as_str()       { if first_cwd.is_empty()    { first_cwd    = c.to_string(); } }
328	                if let Some(b) = v["gitBranch"].as_str() { if first_branch.is_empty() { first_branch = b.to_string(); } }
329	                let parts = parse_user(&v["message"]["content"], &tool_names);
330	                if !parts.is_empty() { cards.push(Card::UserMsg { ts, parts, author: None }); }
331	            }
332	            Some("assistant") => {
333	                let parts = parse_asst(&v["message"]["content"]);
334	                if !parts.is_empty() { cards.push(Card::AsstMsg { ts, parts }); }
335	            }
336	            _ => {}
337	        }
338	    }
339	
340	    let mut result = vec![Card::Header { title, cwd: first_cwd, branch: first_branch, ts: first_ts, agent: agent.to_string() }];
341	    result.extend(cards);
342	
343	    // Merge each pure tool-result UserMsg into the preceding AsstMsg.
344	    let mut i = 1;
345	    while i < result.len() {
346	        let is_pure_results = if let Card::UserMsg { parts, .. } = &result[i] {
347	            parts.iter().all(|p| matches!(p, UserPart::ToolResult { .. }))
348	        } else { false };
349	
350	        if is_pure_results && matches!(&result[i - 1], Card::AsstMsg { .. }) {
351	            let tool_results: Vec<(String, String, bool)> =
352	                if let Card::UserMsg { parts, .. } = &result[i] {
353	                    parts.iter().filter_map(|p| {
354	                        if let UserPart::ToolResult { id, content, is_error, .. } = p {
355	                            Some((id.clone(), content.clone(), *is_error))
356	                        } else { None }
357	                    }).collect()
358	                } else { vec![] };
359	
360	            if let Card::AsstMsg { parts: asst_parts, .. } = &mut result[i - 1] {
361	                for part in asst_parts.iter_mut() {
362	                    if let AsstPart::ToolCall { id, result: res, .. } = part {
363	                        if let Some((_, content, is_error)) =
364	                            tool_results.iter().find(|(rid, _, _)| rid == id)
365	                        {
366	                            *res = Some((content.clone(), *is_error));
367	                        }
368	                    }
369	                }
370	            }
371	            result.remove(i);
372	        } else {
373	            i += 1;
374	        }
375	    }
376	
377	    // Merge consecutive AsstMsg cards so the assistant name appears only once per run.
378	    let mut i = 1;
379	    while i < result.len() {
380	        if matches!(&result[i - 1], Card::AsstMsg { .. }) && matches!(&result[i], Card::AsstMsg { .. }) {
381	            if let Card::AsstMsg { parts: new_parts, .. } = result.remove(i) {
382	                if let Card::AsstMsg { parts, .. } = &mut result[i - 1] {
383	                    parts.extend(new_parts);
384	                }
385	            }
386	        } else {
387	            i += 1;
388	        }
389	    }
390	
391	    // Split each AsstMsg into a text-only AsstMsg (if any text) + a ToolRound (if any tools).
392	    let mut split: Vec<Card> = Vec::with_capacity(result.len());
393	    for card in result {
394	        match card {
395	            Card::AsstMsg { ts, parts } => {
396	                let (text_parts, tool_parts): (Vec<AsstPart>, Vec<AsstPart>) =
397	                    parts.into_iter().partition(|p| matches!(p, AsstPart::Text(_)));
398	                if !text_parts.is_empty() { split.push(Card::AsstMsg  { ts, parts: text_parts }); }
399	                if !tool_parts.is_empty() { split.push(Card::ToolRound { parts: tool_parts }); }
400	            }
401	            other => split.push(other),
402	        }
403	    }
404	    let mut result = split;
405	
406	    // Merge adjacent ToolRound cards (can arise when consecutive asst turns were all-tools).
407	    let mut i = 1;
408	    while i < result.len() {
409	        if matches!(&result[i - 1], Card::ToolRound { .. }) && matches!(&result[i], Card::ToolRound { .. }) {
410	            if let Card::ToolRound { parts: new_parts } = result.remove(i) {
411	                if let Card::ToolRound { parts } = &mut result[i - 1] {
412	                    parts.extend(new_parts);
413	                }
414	            }
415	        } else {
416	            i += 1;
417	        }
418	    }
419	
420	    result
421	}
422	
423	fn parse_user(content: &Value, tool_names: &HashMap<String, String>) -> Vec<UserPart> {
424	    let mut out = Vec::new();
425	    match content {
426	        Value::String(s) if !s.trim().is_empty() => out.push(UserPart::Text(s.clone())),
427	        Value::Array(blocks) => {
428	            for b in blocks {
429	                match b["type"].as_str() {
430	                    Some("text") => {
431	                        if let Some(t) = b["text"].as_str() {
432	                            if !t.trim().is_empty() { out.push(UserPart::Text(t.to_string())); }
433	                        }
434	                    }
435	                    Some("tool_result") => {
436	                        let id = b["tool_use_id"].as_str().unwrap_or("").to_string();
437	                        let name = tool_names.get(&id).cloned().unwrap_or_else(|| "tool".to_string());
438	                        let is_error = b["is_error"].as_bool().unwrap_or(false);
439	                        let content = match &b["content"] {
440	                            Value::String(s) => s.clone(),
441	                            Value::Array(arr) => arr.iter()
442	                                .filter(|x| x["type"].as_str() == Some("text"))
443	                                .filter_map(|x| x["text"].as_str())
444	                                .collect::<Vec<_>>().join("\n"),
445	                            _ => String::new(),
446	                        };
447	                        out.push(UserPart::ToolResult { id, name, content, is_error });
448	                    }
449	                    _ => {}
450	                }
451	            }
452	        }
453	        _ => {}
454	    }
455	    out
456	}
457	
458	fn parse_asst(content: &Value) -> Vec<AsstPart> {
459	    let mut out = Vec::new();
460	    match content {
461	        Value::String(s) if !s.trim().is_empty() => out.push(AsstPart::Text(s.clone())),
462	        Value::Array(blocks) => {
463	            for b in blocks {
464	                match b["type"].as_str() {
465	                    Some("text") => {
466	                        if let Some(t) = b["text"].as_str() {
467	                            if !t.trim().is_empty() { out.push(AsstPart::Text(t.to_string())); }
468	                        }
469	                    }
470	                    Some("tool_use") => {
471	                        out.push(AsstPart::ToolCall {
472	                            id:     b["id"].as_str().unwrap_or("").to_string(),
473	                            name:   b["name"].as_str().unwrap_or("unknown").to_string(),
474	                            input:  b["input"].clone(),
475	                            result: None,
476	                        });
477	                    }
478	                    _ => {}
479	                }
480	            }
481	        }
482	        _ => {}
483	    }
484	    out
485	}
