863	fn wrap(text: &str, width: usize) -> Vec<String> {
864	    if width < 4 { return text.lines().map(str::to_string).collect(); }
865	    let mut out = Vec::new();
866	    for raw_line in text.lines() {
867	        if raw_line.is_empty() { out.push(String::new()); continue; }
868	        let mut remaining = raw_line;
869	        loop {
870	            if remaining.chars().count() <= width {
871	                out.push(remaining.to_string());
872	                break;
873	            }
874	            let break_pos = remaining.chars().take(width)
875	                .collect::<String>()
876	                .rfind(' ')
877	                .unwrap_or(width);
878	            let byte_pos = remaining.char_indices().nth(break_pos)
879	                .map(|(i, _)| i)
880	                .unwrap_or(remaining.len());
881	            out.push(remaining[..byte_pos].to_string());
882	            remaining = remaining[byte_pos..].trim_start_matches(' ');
883	        }
884	    }
885	    out
886	}
