1013	/// Resume a session by ID, falling back to `entire resume` if the Claude JSONL is absent.
1014	/// `fallback_cwd` is used for `entire resume` if the Claude session isn't found.
1015	pub fn resume_session(session_id: &str, fallback_cwd: &str) {
1016	    use std::os::unix::process::CommandExt;
1017	    if let Some((session_cwd, session_branch)) = find_claude_session_cwd(session_id) {
1018	        let launch_dir = if session_cwd.is_empty() || !std::path::Path::new(&session_cwd).exists() {
1019	            fallback_cwd.to_string()
1020	        } else {
1021	            session_cwd
1022	        };
1023	        let err = std::process::Command::new("claude")
1024	            .arg("--resume")
1025	            .arg(session_id)
1026	            .current_dir(&launch_dir)
1027	            .exec();
1028	        eprintln!("exec failed: {err}");
1029	        // exec failed — fall back to entire resume, checking out the session branch first
1030	        resume_via_entire(&launch_dir, &session_branch);
1031	    } else {
1032	        resume_via_entire(fallback_cwd, "");
1033	    }
1034	}
1035	
1036	// ── Pager ─────────────────────────────────────────────────────────────────────
1037	
1038	fn build_flat(
1039	    cards: &[Card],
1040	    term_w: usize,
1041	    collapsed: &std::collections::HashSet<usize>,
1042	) -> (Vec<(usize, String)>, Vec<Selectable>, Vec<usize>) {
1043	    let w = term_w.saturating_sub(2);
1044	    let mut flat: Vec<(usize, String)> = Vec::new();
1045	    let mut selectables: Vec<Selectable> = Vec::new();
1046	    let mut starts: Vec<usize> = Vec::new();
1047	
1048	    // Pull the agent name from the Header card so render_card can use it.
1049	    let agent: &str = cards.iter().find_map(|c| {
1050	        if let Card::Header { agent, .. } = c { Some(agent.as_str()) } else { None }
1051	    }).unwrap_or("");
1052	
1053	    for (card_idx, card) in cards.iter().enumerate() {
1054	        if let Card::ToolRound { parts } = card {
1055	            if collapsed.contains(&card_idx) {
1056	                let si = selectables.len();
1057	                starts.push(flat.len());
1058	                selectables.push(Selectable::Card(card_idx));
1059	                for l in render_tool_summary(parts) { flat.push((si, l)); }
1060	            } else {
1061	                // Header row (collapses the round when space is pressed)
1062	                let si = selectables.len();
1063	                starts.push(flat.len());
1064	                selectables.push(Selectable::ToolHeader(card_idx));
1065	                for l in render_tool_header(parts) { flat.push((si, l)); }
1066	                // One selectable per individual tool call
1067	                for (tool_idx, part) in parts.iter().enumerate() {
1068	                    let si = selectables.len();
1069	                    starts.push(flat.len());
1070	                    selectables.push(Selectable::ToolCall(card_idx, tool_idx));
1071	                    for l in render_one_tool_call(part, w) { flat.push((si, l)); }
1072	                }
1073	            }
1074	        } else {
1075	            let si = selectables.len();
1076	            starts.push(flat.len());
1077	            selectables.push(Selectable::Card(card_idx));
1078	            for l in render_card(card, w, agent) { flat.push((si, l)); }
1079	        }
1080	    }
1081	
1082	    (flat, selectables, starts)
1083	}
1084	
1085	// `Back` returns to whatever called show (the sessions list, the repo TUI, or
1086	// the CLI). `Quit` propagates a full-app exit so q from anywhere quits.
1087	enum PagerOutcome { Back, Quit, Resume, Delete, GoToSessions, GoToRepo(String) }
1088	
1089	fn pager(cards: &[Card], start_ts: Option<&str>) -> Result<PagerOutcome> {
1090	    let (term_w, term_h) = terminal::size().unwrap_or((120, 40));
1091	    let mut w = term_w as usize;
1092	    let mut h = (term_h as usize).saturating_sub(1);
1093	
1094	    let mut collapsed: std::collections::HashSet<usize> = cards.iter().enumerate()
1095	        .filter_map(|(i, c)| if matches!(c, Card::ToolRound { .. }) { Some(i) } else { None })
1096	        .collect();
1097	
1098	    let (mut flat, mut selectables, mut starts) = build_flat(&cards, w, &collapsed);
1099	
1100	    let mut stdout = io::stdout();
1101	
1102	    let orig_hook = std::panic::take_hook();
1103	    std::panic::set_hook(Box::new(move |info| {
1104	        let mut out = io::stdout();
1105	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
1106	        let _ = terminal::disable_raw_mode();
1107	        orig_hook(info);
1108	    }));
1109	
1110	    terminal::enable_raw_mode()?;
1111	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
1112	
1113	    // If a target timestamp was given, jump to the first card whose ts matches.
1114	    // Otherwise land on the first non-navigation card (skip RepoLink and Header).
1115	    let initial_sel = start_ts.and_then(|ts| {
1116	        cards.iter().enumerate().find_map(|(ci, card)| {
1117	            let card_ts = match card {
1118	                Card::UserMsg { ts, .. } | Card::AsstMsg { ts, .. } | Card::System { ts, .. } => ts.as_str(),
1119	                _ => return None,
1120	            };
1121	            if card_ts == ts {
1122	                selectables.iter().position(|s| *s == Selectable::Card(ci))
1123	            } else {
1124	                None
1125	            }
1126	        })
1127	    }).unwrap_or_else(|| selectables.len().saturating_sub(1));
1128	
1129	    let mut sel: usize = initial_sel;
1130	    let mut scroll: usize = 0;
1131	    let mut flash:  Option<&str> = None;
1132	    let mut awaiting_delete = false;
1133	
1134	    let result: Result<PagerOutcome> = loop {
1135	        let s = starts[sel];
1136	        let e = starts.get(sel + 1).copied().unwrap_or(flat.len());
1137	        if s < scroll          { scroll = s; }
1138	        else if e > scroll + h { scroll = e.saturating_sub(h); }
1139	
1140	        if let Err(err) = draw(&mut stdout, &flat, &starts, sel, scroll, h, w, selectables.len(), flash) {
1141	            break Err(anyhow::anyhow!(err));
1142	        }
1143	
1144	        match event::read() {
1145	            Err(e) => break Err(e.into()),
1146	            Ok(Event::Key(k)) => {
1147	                let prev_flash = flash.take();
1148	                match (k.code, k.modifiers) {
1149	                    (KeyCode::Char('q'), _) => break Ok(PagerOutcome::Quit),
1150	                    (KeyCode::Char('c'), KeyModifiers::CONTROL) => break Ok(PagerOutcome::Quit),
1151	                    (KeyCode::Esc | KeyCode::Left, _) => break Ok(PagerOutcome::Back),
1152	                    (KeyCode::Char('r'), _) => break Ok(PagerOutcome::Resume),
1153	                    (KeyCode::Char('d'), _) => {
1154	                        awaiting_delete = true;
1155	                        flash = Some("  Delete session? Press y to confirm, any other key to cancel  ");
1156	                        continue;
1157	                    }
1158	                    (KeyCode::Char('y'), _) if awaiting_delete => {
1159	                        break Ok(PagerOutcome::Delete);
1160	                    }
1161	
1162	                    (KeyCode::Down | KeyCode::Char('j'), _) => {
1163	                        if sel + 1 < selectables.len() { sel += 1; }
1164	                    }
1165	                    (KeyCode::Up | KeyCode::Char('k'), _) => {
1166	                        if sel > 0 { sel -= 1; }
1167	                    }
1168	                    (KeyCode::Char('g'), _) => { sel = 0; }
1169	                    (KeyCode::Char('G'), _) => { sel = selectables.len().saturating_sub(1); }
1170	                    (KeyCode::Char('u'), _) | (KeyCode::PageUp, _) => {
1171	                        scroll = scroll.saturating_sub(h / 2);
1172	                        sel = flat[scroll].0;
1173	                    }
1174	                    (KeyCode::PageDown, _) => {
1175	                        scroll = (scroll + h / 2).min(flat.len().saturating_sub(h));
1176	                        sel = flat[scroll].0;
1177	                    }
1178	
1179	                    (KeyCode::Char('y'), _) | (KeyCode::Char('c'), _) => {
1180	                        let text = match &selectables[sel] {
1181	                            Selectable::Card(ci)         => card_text(&cards[*ci]),
1182	                            Selectable::ToolHeader(ci)   => card_text(&cards[*ci]),
1183	                            Selectable::ToolCall(ci, ti) => {
1184	                                if let Card::ToolRound { parts } = &cards[*ci] {
1185	                                    parts.get(*ti).map_or(String::new(), tool_call_text)
1186	                                } else { String::new() }
1187	                            }
1188	                        };
1189	                        copy_to_clipboard(&text);
1190	                        flash = Some("  ✓ copied to clipboard  ");
1191	                    }
1192	
1193	                    // Space/Right/Enter: expand ToolRound, collapse via header, or navigate
1194	                    (KeyCode::Char(' ') | KeyCode::Right | KeyCode::Enter, _) => {
1195	                        let expand_action = match &selectables[sel] {
1196	                            Selectable::Card(ci) if matches!(&cards[*ci], Card::ToolRound { .. }) => {
1197	                                Some((true, *ci))
1198	                            }
1199	                            Selectable::ToolHeader(ci) => Some((false, *ci)),
1200	                            _ => None,
1201	                        };
1202	                        if let Some((expand, card_idx)) = expand_action {
1203	                            if expand { collapsed.remove(&card_idx); } else { collapsed.insert(card_idx); }
1204	                            let (nf, ns, nst) = build_flat(cards, w, &collapsed);
1205	                            flat   = nf;
1206	                            starts = nst;
1207	                            sel = if expand {
1208	                                ns.iter().position(|s| *s == Selectable::ToolHeader(card_idx))
1209	                            } else {
1210	                                ns.iter().position(|s| *s == Selectable::Card(card_idx))
1211	                            }.unwrap_or_else(|| sel.min(ns.len().saturating_sub(1)));
1212	                            selectables = ns;
1213	                        } else if let Selectable::Card(ci) = &selectables[sel] {
1214	                            match &cards[*ci] {
1215	                                Card::RepoLink { dir, .. } => {
1216	                                    break Ok(PagerOutcome::GoToRepo(dir.clone()));
1217	                                }
1218	                                Card::Header { .. } => {
1219	                                    break Ok(PagerOutcome::GoToSessions);
1220	                                }
1221	                                _ => { flash = prev_flash; }
1222	                            }
1223	                        } else {
1224	                            flash = prev_flash;
1225	                        }
1226	                    }
1227	
1228	                    _ => { awaiting_delete = false; flash = prev_flash; }
1229	                }
1230	            }
1231	            Ok(Event::Resize(new_w, new_h)) => {
1232	                w = new_w as usize;
1233	                h = (new_h as usize).saturating_sub(1);
1234	                let (nf, ns, nst) = build_flat(&cards, w, &collapsed);
1235	                flat = nf; selectables = ns; starts = nst;
1236	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
1237	            }
1238	            Ok(_) => {}
1239	        }
1240	    };
1241	
1242	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
1243	    terminal::disable_raw_mode()?;
1244	    result
1245	}
1246	
1247	fn draw(
1248	    stdout: &mut impl Write,
1249	    flat:   &[(usize, String)],
1250	    starts: &[usize],
1251	    sel:    usize,
1252	    scroll: usize,
1253	    h:      usize,
1254	    w:      usize,
1255	    total:  usize,
1256	    flash:  Option<&str>,
1257	) -> io::Result<()> {
1258	    use crossterm::queue;
1259	    let sel_bg = crate::theme::get().sel_bg;
1260	
1261	    let end = (scroll + h).min(flat.len());
1262	
1263	    // Build the entire frame into one buffer; flush once to eliminate flicker.
1264	    // Use explicit cursor::MoveTo per row so embedded newlines in content can't
1265	    // shift subsequent rows into the wrong position.
1266	    let mut buf: Vec<u8> = Vec::with_capacity((w + 40) * (h + 2));
1267	
1268	    for row in 0..h {
1269	        queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
1270	
1271	        let flat_idx = scroll + row;
1272	        if flat_idx < end {
1273	            let (card_idx, line) = &flat[flat_idx];
1274	            if *card_idx == sel {
1275	                let line_bg = with_bg(line, sel_bg);
1276	                let vis = visible_width(line);
1277	                let pad = w.saturating_sub(vis);
1278	                write!(buf, "\x1b[{sel_bg}m{line_bg}{}\x1b[0m", " ".repeat(pad))?;
1279	            } else {
1280	                buf.extend_from_slice(line.as_bytes());
1281	            }
1282	        }
1283	    }
1284	
1285	    // Status bar
1286	    let sel_end = starts.get(sel + 1).copied().unwrap_or(flat.len());
1287	    let base = format!(
1288	        "  {}/{} msgs  lines {}-{}  j/k ↑↓ navigate  u/PgDn page  g/G ends  y/c copy  r resume  d delete  q quit  ",
1289	        sel + 1, total, starts[sel] + 1, sel_end,
1290	    );
1291	    let bar = if let Some(msg) = flash {
1292	        let skip = msg.chars().count();
1293	        let rest: String = base.chars().skip(skip).collect();
1294	        format!("{msg}{rest}")
1295	    } else {
1296	        base
1297	    };
1298	    let bar_display: String = bar.chars().take(w).collect();
1299	    let padded = format!("{bar_display:width$}", width = w);
1300	    queue!(buf, cursor::MoveTo(0, h as u16))?;
1301	    write!(buf, "\x1b[7m{padded}\x1b[0m")?;
1302	
1303	    stdout.write_all(&buf)?;
1304	    stdout.flush()
1305	}
