/// Search all local branches for a commit whose body contains
/// `Entire-Checkpoint: <id>` and return its subject line.
fn find_checkpoint_commit_message(repo_dir: &str, checkpoint_id: &str) -> Option<String> {
    let grep_pat = format!("Entire-Checkpoint: {checkpoint_id}");
    let out = Command::new("git")
        .args(["log", "--all", &format!("--grep={grep_pat}"), "--format=%s", "-1"])
        .current_dir(repo_dir)
        .output()
        .ok()?;
    if !out.status.success() { return None; }
    let msg = String::from_utf8_lossy(&out.stdout).trim().to_string();
    if msg.is_empty() { None } else { Some(msg) }
}

