9	pub(crate) const BRANCH: &str = "entire/checkpoints/v1";
10	
11	/// Resolves a session's owning repository. Remote URL is the source of truth
12	/// — local paths are incidental to where someone happened to clone a repo.
13	/// Order of precedence:
14	///   1. **Mode B** (indexed repo's remote IS some tracked project's declared
15	///      `.entire/settings.json::checkpoint_remote`): pick the project that
16	///      uses this shared checkpoint repo; disambiguate by cwd if multiple.
17	///   2. **Mode A** (we have an indexing context but it isn't a shared
18	///      checkpoint repo): the file IS in this repo's checkpoint branch, so
19	///      by direct evidence it's this repo's session. The indexing context's
20	///      remote URL is authoritative — no need to consult the cwd.
21	///   3. **Backfill / no indexing context**: derive remote from cwd.
22	///      a. `git -C cwd remote get-url origin` matched against `repositories.remote`
23	///      b. cwd longest-prefix against tracked dirs (cross-machine fallback)
24	///      c. user-home-stripped suffix match (Scott's `/Users/sholodak/cosmos/X`
25	///         matches my `/Users/stsoucas/cosmos/X`)
26	///   4. Returns None if no signal at all.
27	///
28	/// Results of `git remote get-url origin` are cached so the cwd-derivation
29	/// path doesn't shell out repeatedly during a long index.
30	pub(crate) struct RepoResolver {
31	    repos: Vec<(i64, String, String)>,           // (id, directory, remote)
32	    by_remote: HashMap<String, i64>,             // normalized remote URL → repo_id
33	    project_for_checkpoint: HashMap<String, Vec<i64>>, // normalized cp-remote URL → project ids
34	    cwd_remote_cache: RefCell<HashMap<String, Option<String>>>,
35	}
36	
37	impl RepoResolver {
38	    pub fn new(conn: &rusqlite::Connection) -> Result<Self> {
39	        let mut stmt = conn.prepare("SELECT id, directory, remote FROM repositories")?;
40	        let repos: Vec<(i64, String, String)> = stmt
41	            .query_map([], |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)))?
42	            .collect::<Result<_, _>>()?;
43	
44	        let mut by_remote = HashMap::new();
45	        let mut project_for_checkpoint: HashMap<String, Vec<i64>> = HashMap::new();
46	        for (id, dir, remote) in &repos {
47	            if !remote.is_empty() {
48	                by_remote.insert(normalize_remote(remote), *id);
49	            }
50	            if let Some(cp_url) = checkpoint_remote_url(dir) {
51	                project_for_checkpoint.entry(normalize_remote(&cp_url))
52	                    .or_default()
53	                    .push(*id);
54	            }
55	        }
56	
57	        Ok(Self {
58	            repos,
59	            by_remote,
60	            project_for_checkpoint,
61	            cwd_remote_cache: RefCell::new(HashMap::new()),
62	        })
63	    }
64	
65	    pub fn resolve(&self, cwd: &str, indexing_context: Option<i64>) -> Option<i64> {
66	        // ── INDEXING CONTEXT (when we have one) ────────────────────────
67	        // We know the remote URL of the repo we're scanning — that IS the
68	        // session's remote URL, modulo the Mode B fan-out.
69	        if let Some(ctx_id) = indexing_context {
70	            if let Some(ctx_remote) = self.remote_of(ctx_id) {
71	                // 1. Mode B: ctx is a shared checkpoint repo. Disambiguate
72	                //    among the projects that use it as their checkpoint
73	                //    remote.
74	                if let Some(candidates) = self.project_for_checkpoint.get(&ctx_remote) {
75	                    if candidates.len() == 1 { return Some(candidates[0]); }
76	                    for &cand in candidates {
77	                        if let Some((_, dir, _)) = self.repos.iter().find(|(id, _, _)| *id == cand) {
78	                            if let Some(name) = std::path::Path::new(dir).file_name().and_then(|s| s.to_str()) {
79	                                if cwd.contains(name) { return Some(cand); }
80	                            }
81	                        }
82	                    }
83	                    if !candidates.is_empty() { return Some(candidates[0]); }
84	                }
85	                // 2. Mode A: ctx IS the project. Direct evidence — the file
86	                //    is in this repo's checkpoint branch — beats any cwd
87	                //    heuristic we could run.
88	                return Some(ctx_id);
89	            }
90	        }
91	
92	        // ── NO INDEXING CONTEXT (backfill) ─────────────────────────────
93	        // We're walking ~/.claude/projects without knowing which repo's
94	        // branch each session came from. Derive remote from cwd.
95	
96	        // 3a. cwd is a local git workdir — ask it for origin URL.
97	        if !cwd.is_empty() {
98	            if let Some(remote_url) = self.cached_origin(cwd) {
99	                if let Some(&id) = self.by_remote.get(&normalize_remote(&remote_url)) {
100	                    return Some(id);
101	                }
102	            }
103	        }
104	
105	        // 3b/c. Path heuristics — brittle, but the only thing left for
106	        //       cross-machine cwds that don't exist locally.
107	        self.from_path(cwd)
108	    }
109	
110	    fn from_path(&self, cwd: &str) -> Option<i64> {
111	        if cwd.is_empty() { return None; }
112	        // a) cwd is literally inside a tracked dir.
113	        let mut best: Option<(usize, i64)> = None;
114	        for (id, dir, _) in &self.repos {
115	            if cwd.starts_with(dir.as_str()) {
116	                let n = dir.len();
117	                if best.map_or(true, |(b, _)| n > b) { best = Some((n, *id)); }
118	            }
119	        }
120	        if let Some((_, id)) = best { return Some(id); }
121	
122	        // b) Same project, different user-home. `/Users/sholodak/cosmos/foo`
123	        //    matches my `/Users/stsoucas/cosmos/foo` after stripping the
124	        //    leading `/Users/<user>/`.
125	        let cwd_suffix = strip_user_home(cwd)?;
126	        let mut best: Option<(usize, i64)> = None;
127	        for (id, dir, _) in &self.repos {
128	            if let Some(dir_suffix) = strip_user_home(dir) {
129	                if path_prefix_match(cwd_suffix, dir_suffix) {
130	                    let n = dir_suffix.len();
131	                    if best.map_or(true, |(b, _)| n > b) { best = Some((n, *id)); }
132	                }
133	            }
134	        }
135	        best.map(|(_, id)| id)
136	    }
137	
138	    fn remote_of(&self, repo_id: i64) -> Option<String> {
139	        self.repos.iter().find(|(id, _, _)| *id == repo_id).map(|(_, _, r)| normalize_remote(r))
140	    }
141	
142	    fn cached_origin(&self, cwd: &str) -> Option<String> {
143	        let mut cache = self.cwd_remote_cache.borrow_mut();
144	        if let Some(hit) = cache.get(cwd) { return hit.clone(); }
145	        let resolved = git_origin_url(cwd);
146	        cache.insert(cwd.to_string(), resolved.clone());
147	        resolved
148	    }
149	}
