151	fn git_origin_url(cwd: &str) -> Option<String> {
152	    if !std::path::Path::new(cwd).is_dir() { return None; }
153	    let out = Command::new("git")
154	        .args(["remote", "get-url", "origin"])
155	        .current_dir(cwd)
156	        .output().ok()?;
157	    if !out.status.success() { return None; }
158	    let s = String::from_utf8(out.stdout).ok()?;
159	    let s = s.trim();
160	    if s.is_empty() { None } else { Some(s.to_string()) }
161	}
