use anyhow::{Context, Result};
use dirs::home_dir;
use rusqlite::Connection;
use std::fs;

pub fn connect() -> Result<Connection> {
    let gossamer_dir = home_dir()
        .context("cannot determine home directory")?
        .join(".gossamer");

    fs::create_dir_all(&gossamer_dir).context("failed to create ~/.gossamer")?;

    let db_path = gossamer_dir.join("gossamer.db");
    let conn = Connection::open(&db_path).context("failed to open database")?;

    conn.execute_batch("
        CREATE TABLE IF NOT EXISTS repositories (
            id       INTEGER PRIMARY KEY AUTOINCREMENT,
            directory TEXT NOT NULL UNIQUE,
            remote   TEXT NOT NULL,
            name     TEXT NOT NULL
        );")
    .context("failed to run schema migrations")?;

    // Idempotent column additions (ignored if column already exists)
    let _ = conn.execute("ALTER TABLE repositories ADD COLUMN last_indexed_commit TEXT", []);
    let _ = conn.execute("ALTER TABLE repositories ADD COLUMN last_search_commit TEXT", []);
    let _ = conn.execute("ALTER TABLE checkpoints ADD COLUMN jsonl_path TEXT", []);
    let _ = conn.execute("ALTER TABLE checkpoints ADD COLUMN repo_dir TEXT", []);
    let _ = conn.execute("ALTER TABLE checkpoints ADD COLUMN os_user TEXT", []);
    let _ = conn.execute("ALTER TABLE checkpoints ADD COLUMN commit_message TEXT", []);
    let _ = conn.execute("ALTER TABLE checkpoints ADD COLUMN turn_id TEXT", []);
    let _ = conn.execute("ALTER TABLE checkpoints ADD COLUMN checkpoint_id TEXT", []);
    let _ = conn.execute("ALTER TABLE checkpoints ADD COLUMN files_touched TEXT", []);
    let _ = conn.execute("ALTER TABLE checkpoints ADD COLUMN token_usage TEXT", []);
    let _ = conn.execute("ALTER TABLE checkpoints ADD COLUMN initial_attribution TEXT", []);
    let _ = conn.execute("ALTER TABLE checkpoints ADD COLUMN model TEXT", []);

    // Migrate checkpoints PK from (session_id, checkpoint_number) → (session_id, checkpoint_id).
    // The old per-directory sequence number (always 0 for one-commit-per-checkpoint repos)
    // caused collisions when a session had multiple checkpoint commits.
    migrate_checkpoints_pk(&conn);
    let _ = conn.execute("ALTER TABLE sessions ADD COLUMN branch TEXT", []);
    let _ = conn.execute("ALTER TABLE sessions ADD COLUMN repo_id INTEGER", []);
    let _ = conn.execute("ALTER TABLE sessions ADD COLUMN name_is_explicit INTEGER NOT NULL DEFAULT 0", []);

    // Correct sessions whose stored repo_id doesn't match their cwd. Done in
    // two passes so cross-machine sessions (Scott's `/Users/sholodak/…`) also
    // get re-attributed instead of stranding on whichever repo's index pass
    // last touched them.
    correct_session_repo_attribution(&conn);

    conn.execute_batch("
        CREATE TABLE IF NOT EXISTS sessions (
            session_id   TEXT PRIMARY KEY,
            agent_name   TEXT NOT NULL,
            user         TEXT NOT NULL,
            created_at   TEXT NOT NULL,
            updated_at   TEXT NOT NULL,
            cwd          TEXT NOT NULL,
            session_name TEXT NOT NULL,
            tokens_used  INTEGER NOT NULL DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS event_log (
            id         INTEGER PRIMARY KEY AUTOINCREMENT,
            session_id TEXT NOT NULL,
            message_id TEXT NOT NULL,
            type       TEXT NOT NULL,
            data       TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS checkpoints (
            session_id          TEXT NOT NULL,
            checkpoint_id       TEXT NOT NULL DEFAULT '',
            commit_sha          TEXT NOT NULL DEFAULT '',
            author_name         TEXT NOT NULL DEFAULT '',
            author_email        TEXT NOT NULL DEFAULT '',
            last_turn_ts        TEXT NOT NULL DEFAULT '',
            jsonl_path          TEXT,
            repo_dir            TEXT,
            os_user             TEXT,
            commit_message      TEXT,
            turn_id             TEXT,
            files_touched       TEXT,
            token_usage         TEXT,
            initial_attribution TEXT,
            model               TEXT,
            PRIMARY KEY (session_id, checkpoint_id)
        );
        CREATE INDEX IF NOT EXISTS checkpoints_session_idx
            ON checkpoints (session_id, last_turn_ts);
    ")
    .context("failed to run schema migrations")?;

    Ok(conn)
}

/// Re-resolve `sessions.repo_id` using path-only heuristics: cwd longest-
/// prefix match, then user-home-stripped suffix match (so Scott's
/// `/Users/sholodak/cosmos/cosmos-graphql` attaches to our local
/// `/Users/stsoucas/cosmos/cosmos-graphql` clone). Mirrors steps 1 and 1b of
/// `index::RepoResolver` but skips the git-remote subprocess — the migration
/// runs on every connect and must stay cheap.
fn migrate_checkpoints_pk(conn: &Connection) {
    // Only run if the table still uses the old (session_id, checkpoint_number) primary key.
    let schema: String = conn.query_row(
        "SELECT COALESCE(sql,'') FROM sqlite_master WHERE type='table' AND name='checkpoints'",
        [], |r| r.get(0),
    ).unwrap_or_default();

    // New schema has checkpoint_id as NOT NULL in the PK; old one has checkpoint_number as PK.
    if !schema.contains("PRIMARY KEY (session_id, checkpoint_number)") { return; }

    let _ = conn.execute_batch("
        CREATE TABLE IF NOT EXISTS checkpoints_new (
            session_id          TEXT NOT NULL,
            checkpoint_id       TEXT NOT NULL DEFAULT '',
            commit_sha          TEXT NOT NULL DEFAULT '',
            author_name         TEXT NOT NULL DEFAULT '',
            author_email        TEXT NOT NULL DEFAULT '',
            last_turn_ts        TEXT NOT NULL DEFAULT '',
            jsonl_path          TEXT,
            repo_dir            TEXT,
            os_user             TEXT,
            commit_message      TEXT,
            turn_id             TEXT,
            files_touched       TEXT,
            token_usage         TEXT,
            initial_attribution TEXT,
            model               TEXT,
            PRIMARY KEY (session_id, checkpoint_id)
        );
        INSERT OR IGNORE INTO checkpoints_new
            SELECT
                session_id,
                CASE WHEN checkpoint_id IS NOT NULL AND checkpoint_id != ''
                     THEN checkpoint_id
                     ELSE 'legacy-' || CAST(checkpoint_number AS TEXT)
                END,
                COALESCE(commit_sha,   ''),
                COALESCE(author_name,  ''),
                COALESCE(author_email, ''),
                COALESCE(last_turn_ts, ''),
                jsonl_path, repo_dir, os_user,
                commit_message, turn_id, files_touched, token_usage,
                initial_attribution, model
            FROM checkpoints;
        DROP TABLE checkpoints;
        ALTER TABLE checkpoints_new RENAME TO checkpoints;
        CREATE INDEX IF NOT EXISTS checkpoints_session_idx
            ON checkpoints (session_id, last_turn_ts);
    ");
}

fn correct_session_repo_attribution(conn: &Connection) {
    let repos: Vec<(i64, String)> = match conn.prepare("SELECT id, directory FROM repositories") {
        Ok(mut stmt) => stmt.query_map([], |r| Ok((r.get(0)?, r.get(1)?)))
            .map(|rs| rs.flatten().collect())
            .unwrap_or_default(),
        Err(_) => return,
    };
    if repos.is_empty() { return; }

    let sessions: Vec<(String, String, Option<i64>)> = match conn.prepare(
        "SELECT session_id, cwd, repo_id FROM sessions WHERE cwd IS NOT NULL AND cwd != ''"
    ) {
        Ok(mut stmt) => stmt.query_map([], |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)))
            .map(|rs| rs.flatten().collect())
            .unwrap_or_default(),
        Err(_) => return,
    };

    for (sid, cwd, current) in sessions {
        let resolved = resolve_by_path(&repos, &cwd);
        if let Some(new_id) = resolved {
            if current != Some(new_id) {
                let _ = conn.execute(
                    "UPDATE sessions SET repo_id = ?1 WHERE session_id = ?2",
                    rusqlite::params![new_id, sid],
                );
            }
        }
    }
}

fn resolve_by_path(repos: &[(i64, String)], cwd: &str) -> Option<i64> {
    let mut best: Option<(usize, i64)> = None;
    for (id, dir) in repos {
        if cwd.starts_with(dir.as_str()) {
            let n = dir.len();
            if best.map_or(true, |(b, _)| n > b) { best = Some((n, *id)); }
        }
    }
    if let Some((_, id)) = best { return Some(id); }

    let cwd_suffix = strip_user_home(cwd)?;
    let mut best: Option<(usize, i64)> = None;
    for (id, dir) in repos {
        if let Some(dir_suffix) = strip_user_home(dir) {
            if path_prefix_match(cwd_suffix, dir_suffix) {
                let n = dir_suffix.len();
                if best.map_or(true, |(b, _)| n > b) { best = Some((n, *id)); }
            }
        }
    }
    best.map(|(_, id)| id)
}

fn strip_user_home(path: &str) -> Option<&str> {
    for home_root in ["/Users/", "/home/"] {
        if let Some(rest) = path.strip_prefix(home_root) {
            return rest.split_once('/').map(|(_user, after)| after);
        }
    }
    None
}

fn path_prefix_match(haystack: &str, needle: &str) -> bool {
    if haystack == needle { return true; }
    if !haystack.starts_with(needle) { return false; }
    haystack.as_bytes().get(needle.len()) == Some(&b'/')
}

use std::sync::OnceLock;
use std::time::Duration;

// ── SGR parameter strings for the standard 16 ANSI colors ────────────────────
// These map to whatever palette the user's terminal defines (Solarized, Nord,
// Dracula, etc.) — the terminal theme controls the actual RGB values.

// Foreground — standard
const BLACK:   &str = "30";
const RED:     &str = "31";
const GREEN:   &str = "32";
const YELLOW:  &str = "33";
const BLUE:    &str = "34";
const MAGENTA: &str = "35";
const CYAN:    &str = "36";
const WHITE:   &str = "37"; // color-7: "gray" in dark themes, base text in Solarized

// Foreground — bright ("intense") variants
const BRIGHT_BLACK:   &str = "90"; // dark gray — universally readable as "dim"
const BRIGHT_GREEN:   &str = "92";
const BRIGHT_CYAN:    &str = "96";
const BRIGHT_WHITE:   &str = "97";

// Background
const BG_DARK_GREEN:   &str = "48;5;22";  // 256-color very dark green (#005f00)
const BG_BRIGHT_GREEN: &str = "102";      // bright/intense green background
const BG_BRIGHT_BLACK: &str = "100"; // dark gray bg — visible selection on both dark and light

// Bold + color composites (bold attribute + standard color in one SGR string)
const BOLD_YELLOW:       &str = "1;33";
const BOLD_BLUE:         &str = "1;34";
const BOLD_RED:          &str = "1;31";
const BOLD_WHITE:        &str = "1;97";
const BOLD_BLACK:        &str = "1;30";
const BOLD_BRIGHT_GREEN: &str = "1;92";

// ── Theme struct ──────────────────────────────────────────────────────────────

pub struct Theme {
    /// Row selection background ("48;5;N" or base-16 bg code)
    pub sel_bg: &'static str,
    /// Dim text color when rendered on top of sel_bg (replaces text_dim/text_faint so it stays readable)
    pub sel_text_dim: &'static str,

    /// Metadata, timestamps, paths, decorative separators
    pub text_dim: &'static str,
    /// Very secondary ("… N more lines", non-backed meta)
    pub text_faint: &'static str,
    /// Normal readable foreground text
    pub text_primary: &'static str,
    /// Tool input secondary argument lines
    pub text_secondary: &'static str,

    /// Recent/active indicator — green
    pub fresh: &'static str,
    /// Moderate age / soft warning — yellow/amber
    pub moderate: &'static str,
    /// Inactive branch / stale state — gray
    pub stale: &'static str,
    /// Errors, detached HEAD — red
    pub error: &'static str,

    /// Bold section/page headers
    pub header: &'static str,
    /// Non-bold accent: main branch name
    pub accent: &'static str,
    /// Inline label color: branch tags, tool names
    pub label: &'static str,
    /// Linked worktrees, backed-up branches
    pub link: &'static str,

    /// Backed-up session name column (bold)
    pub backed_name: &'static str,
    /// Backed-up session metadata column
    pub backed_meta: &'static str,
    /// Non-backed session name column
    pub unbacked_name: &'static str,
    /// Non-backed session metadata column
    pub unbacked_meta: &'static str,

    /// Non-error tool result — magenta/purple
    pub tool_ok: &'static str,
    /// Bold tidy panel warning title — red
    pub tidy_warn: &'static str,

    // ── Checkpoint row ────────────────────────────────────────────────────────
    /// Full-width background for checkpoint rows
    pub checkpoint_bg:    &'static str,
    /// "checkpoint" label text (bold, reads as light green on the bg)
    pub checkpoint_label: &'static str,
    /// Commit message and checkpoint number
    pub checkpoint_text:  &'static str,
    /// Dimmed metadata: short ID, timestamp
    pub checkpoint_dim:   &'static str,

    // ── Markdown skin (crossterm Color, passed directly to MadSkin) ──────────
    pub md_code: crossterm::style::Color,
    pub md_text: crossterm::style::Color,
    pub md_h1:   crossterm::style::Color,
    pub md_h2:   crossterm::style::Color,
    pub md_h3:   crossterm::style::Color,
    pub md_bold: crossterm::style::Color,
    pub md_italic: crossterm::style::Color,
}

// ── Palettes ──────────────────────────────────────────────────────────────────

pub fn dark() -> Theme {
    use crossterm::style::Color;
    Theme {
        sel_bg:         BG_BRIGHT_BLACK,  // dark gray bg — subtle selection on dark terminal
        sel_text_dim:   BRIGHT_WHITE,     // bright white — maximally readable on dark gray sel bg
        text_dim:       BRIGHT_BLACK,     // gray — metadata, separators
        text_faint:     BRIGHT_BLACK,     // same gray — "N more lines" etc.
        text_primary:   BRIGHT_WHITE,     // near-white — primary readable text
        text_secondary: WHITE,            // color-7 — slightly dimmer than primary
        fresh:          BRIGHT_GREEN,     // vivid green — very recent
        moderate:       YELLOW,           // yellow — moderate age
        stale:          BRIGHT_BLACK,     // gray — inactive
        error:          RED,              // red — detached, errors
        header:         BOLD_YELLOW,      // bold yellow — section titles
        accent:         YELLOW,           // yellow — main branch
        label:          CYAN,             // cyan — inline labels, tool names
        link:           BRIGHT_CYAN,      // bright cyan — linked worktrees, backed-up branches
        backed_name:    BOLD_WHITE,       // bold bright white — prominent session name
        backed_meta:    BRIGHT_BLACK,     // gray — id, timestamp
        unbacked_name:  WHITE,            // color-7 — dimmer, not backed up
        unbacked_meta:  BRIGHT_BLACK,     // gray
        tool_ok:          MAGENTA,          // magenta — non-error tool result
        tidy_warn:        "1;91",           // bold bright red — destructive action warning
        checkpoint_bg:    BG_DARK_GREEN,     // very dark green (#005f00) — explicit 256-color
        checkpoint_label: BOLD_BRIGHT_GREEN, // bold bright green — "light green on dark green"
        checkpoint_text:  BRIGHT_WHITE,      // near-white — commit message, number
        checkpoint_dim:   WHITE,             // color-7 — short ID, timestamp
        md_code:        Color::Cyan,
        md_text:        Color::Grey,
        md_h1:          Color::Yellow,
        md_h2:          Color::DarkYellow,
        md_h3:          Color::DarkCyan,
        md_bold:        Color::White,
        md_italic:      Color::Grey,
    }
}

pub fn light() -> Theme {
    use crossterm::style::Color;
    Theme {
        sel_bg:         BG_BRIGHT_BLACK,  // dark gray bg — clearly visible on light terminal
        sel_text_dim:   BRIGHT_WHITE,     // bright white — maximally readable on dark gray sel bg
        text_dim:       BRIGHT_BLACK,     // dark gray — same, readable on light bg
        text_faint:     BRIGHT_BLACK,
        text_primary:   BLACK,            // near-black — primary text on light bg
        text_secondary: BRIGHT_BLACK,     // dark gray
        fresh:          GREEN,            // dark green — more readable on light than bright green
        moderate:       YELLOW,           // yellow — same
        stale:          WHITE,            // color-7 — subtle on light
        error:          RED,              // dark red — better contrast on light than bright red
        header:         BOLD_BLUE,        // bold blue — yellow has poor contrast on white bg
        accent:         BLUE,             // blue — main branch on light bg
        label:          CYAN,             // cyan — same
        link:           BLUE,             // blue — more readable than cyan on light bg
        backed_name:    BOLD_BLACK,       // bold black — prominent on light bg
        backed_meta:    BRIGHT_BLACK,     // dark gray
        unbacked_name:  BRIGHT_BLACK,     // dark gray
        unbacked_meta:  BRIGHT_BLACK,
        tool_ok:          MAGENTA,          // same
        tidy_warn:        BOLD_RED,         // bold red
        checkpoint_bg:    BG_BRIGHT_GREEN,   // bright green background for light terminals
        checkpoint_label: BOLD_BLACK,       // bold black — best contrast on bright green bg
        checkpoint_text:  BLACK,            // black — best contrast on bright green bg
        checkpoint_dim:   BRIGHT_BLACK,     // dark gray — dimmed metadata on bright green bg
        md_code:        Color::DarkCyan,
        md_text:        Color::Black,
        md_h1:          Color::DarkBlue,
        md_h2:          Color::DarkBlue,
        md_h3:          Color::DarkCyan,
        md_bold:        Color::Black,
        md_italic:      Color::DarkGrey,
    }
}

// ── Detection ─────────────────────────────────────────────────────────────────

static THEME: OnceLock<Theme> = OnceLock::new();

pub fn get() -> &'static Theme {
    THEME.get_or_init(detect)
}

fn detect() -> Theme {
    // 1. Explicit user override — always wins
    if let Ok(v) = std::env::var("GOSSAMER_THEME") {
        match v.to_lowercase().as_str() {
            "light" => return light(),
            "dark"  => return dark(),
            _ => {}
        }
    }

    // 2. OSC 11 query — ask the terminal for its background color
    //    termbg sends ESC ]11;?ST, reads the RGB response, and classifies it.
    //    This works on most modern terminals (kitty, Alacritty, iTerm2, VTE, xterm).
    //    Terminals that ignore OSC 11 cause a timeout; we fall through to step 3.
    if let Ok(termbg::Theme::Light) = termbg::theme(Duration::from_millis(100)) {
        return light();
    }

    // 3. COLORFGBG="fg;bg" — set by some older terminals (rxvt, etc.)
    //    Background index 7 (white) or 15 (bright white) → light theme.
    if let Ok(v) = std::env::var("COLORFGBG") {
        if let Some(bg) = v.rsplit(';').next().and_then(|s| s.trim().parse::<u8>().ok()) {
            if bg == 7 || bg == 15 {
                return light();
            }
        }
    }

    // 4. Default to dark
    dark()
}

pub mod claude_code;

use anyhow::Result;

pub struct ParsedSession {
    pub session_id: String,
    pub agent_name: String,
    pub created_at: String,   // RFC 3339
    pub updated_at: String,   // RFC 3339
    pub cwd: String,
