use anyhow::{Context, Result};
use chrono::{DateTime, Utc};
use crossterm::{
    cursor,
    event::{self, Event, KeyCode},
    execute,
    terminal::{self, ClearType, EnterAlternateScreen, LeaveAlternateScreen},
};
use std::io::{self, IsTerminal, Write};

// ── Hit types ─────────────────────────────────────────────────────────────────

#[derive(Clone)]
enum HitKind {
    Log,
    Session,
    Repo,
}

impl HitKind {
    fn label(&self) -> &'static str {
        match self {
            HitKind::Log     => "log",
            HitKind::Session => "ses",
            HitKind::Repo    => "rep",
        }
    }
}

struct SearchHit {
    kind: HitKind,
    title: String,
    dir: String,
    excerpt_lines: Vec<String>, // context lines: prev turn, matched turn, next turn
    session_id: Option<String>,
    repo_dir: Option<String>,
    start_ts: Option<String>,   // for navigation in show::run_at
    hit_ts: Option<String>,     // timestamp of the matched turn (for display)
    branch: String,
    // enriched from gossamer DB after search
    agent: String,
    backed_up: bool,
    updated_at: String,
    remote: String,
    author: String, // session author (first-checkpoint commit author), name > email > os_user
}

// Groups hits from the same session together under one header row.
struct Group {
    title: String,
    dir: String,
    branch: String,
    agent: String,
    backed_up: bool,
    updated_at: String,
    remote: String,
    session_id: Option<String>,
    repo_dir: Option<String>,
    kind: HitKind,
    rows: Vec<GroupRow>,
    author: String,
}

struct GroupRow {
    hit_ts: Option<String>,
    start_ts: Option<String>,
    lines: Vec<String>,
}

