        let os_user_str = p.os_user.unwrap_or_default();

        // Prefer the working-branch commit SHA; fall back to checkpoint-branch SHA.
        let (branch_sha, commit_message) = cp_commit_map
            .get(&p.checkpoint_id)
            .map(|(s, m)| (s.as_str(), m.as_str()))
            .unwrap_or(("", ""));
