131	    enrich_hits(&mut hits);
132	
133	    let groups = build_groups(hits);
134	
135	    if json || !io::stdout().is_terminal() {
136	        let arr: Vec<serde_json::Value> = groups.iter().map(|g| {
137	            let hits_json: Vec<serde_json::Value> = g.rows.iter().map(|r| serde_json::json!({
138	                "timestamp": r.hit_ts,
139	                "excerpt": r.lines.join(" "),
140	            })).collect();
141	            serde_json::json!({
142	                "kind": g.kind.label(),
143	                "session_id": g.session_id,
144	                "session_name": g.title,
145	                "dir": g.dir,
146	                "branch": g.branch,
147	                "author": g.author,
148	                "agent": g.agent,
149	                "updated_at": g.updated_at,
150	                "backed_up": g.backed_up,
151	                "remote": g.remote,
152	                "hits": hits_json,
153	            })
154	        }).collect();
155	        println!("{}", serde_json::to_string_pretty(&serde_json::json!({
156	            "query": query,
157	            "results": arr,
158	        }))?);
159	        return Ok(false);
160	    }
161	
162	    let orig_hook = std::panic::take_hook();
163	    std::panic::set_hook(Box::new(move |info| {
164	        let mut out = io::stdout();
165	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
166	        let _ = terminal::disable_raw_mode();
167	        orig_hook(info);
168	    }));
169	
170	    let mut stdout = io::stdout();
171	    terminal::enable_raw_mode()?;
172	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
173	
174	    let result = tui_loop(&mut stdout, &groups, query, ms);
175	
176	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
177	    terminal::disable_raw_mode()?;
178	
179	    result
180	}
