182	/// The ingest pipeline prefixes user turns with `[User] ` so the embedded
183	/// body string distinguishes roles. The author column now carries that
184	/// information at the row level, so strip the inline tag from excerpts.
185	fn strip_user_label(s: &str) -> String {
186	    s.strip_prefix("[User] ")
187	        .or_else(|| s.strip_prefix("[User]"))
188	        .unwrap_or(s)
189	        .to_string()
190	}
