192	// ── Hit parsing ───────────────────────────────────────────────────────────────
193	
194	fn parse_hit(metadata_json: &str, bodies: &[String], sub_idx: u32) -> SearchHit {
195	    let sub_idx = sub_idx as usize;
196	    let meta: serde_json::Value = serde_json::from_str(metadata_json).unwrap_or_default();
197	    let source = meta["source"].as_str().unwrap_or("claude");
198	
199	    match source {
200	        "session" => {
201	            let name = meta["session_name"].as_str().unwrap_or("").to_string();
202	            let cwd  = meta["cwd"].as_str().unwrap_or("").to_string();
203	            SearchHit {
204	                kind: HitKind::Session,
205	                title: name,
206	                dir: super::short_path(&cwd),
207	                excerpt_lines: vec![],
208	                session_id: meta["session_id"].as_str().map(str::to_string),
209	                repo_dir: None,
210	                turn_id: None, hit_ts: None, branch: String::new(),
211	                agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
212	                remote: String::new(),
213	            }
214	        }
215	        "repo" => {
216	            let name = meta["repo_name"].as_str().unwrap_or("").to_string();
217	            let dir  = meta["repo_dir"].as_str().unwrap_or("").to_string();
218	            SearchHit {
219	                kind: HitKind::Repo,
220	                title: name,
221	                dir: super::short_path(&dir),
222	                excerpt_lines: vec![],
223	                session_id: None,
224	                repo_dir: Some(dir),
225	                turn_id: None, hit_ts: None, branch: String::new(),
226	                agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
227	                remote: String::new(),
228	            }
229	        }
230	        "checkpoint" => {
231	            let name    = meta["session_name"].as_str().unwrap_or("").to_string();
232	            let project = meta["project"].as_str().unwrap_or("").to_string();
233	            let message = bodies.first()
234	                .and_then(|b| b.lines().find(|l| l.starts_with("[Checkpoint] ")))
235	                .map(|l| l.trim_start_matches("[Checkpoint] ").to_string())
236	                .unwrap_or_default();
237	            SearchHit {
238	                kind: HitKind::Checkpoint,
239	                title: name,
240	                dir: super::short_path(&project),
241	                excerpt_lines: if message.is_empty() { vec![] } else { vec![message] },
242	                session_id: meta["session_id"].as_str().map(str::to_string),
243	                repo_dir: None,
244	                turn_id: None,
245	                hit_ts: None,
246	                branch: String::new(),
247	                agent: String::new(), backed_up: false, updated_at: String::new(),
248	                author: String::new(), remote: String::new(),
249	            }
250	        }
251	        _ => {
252	            // "claude" — session log turn.
253	            // sub_idx=0 means the [project] header line matched — not a useful
254	            // content hit (session-name matching is handled separately). Drop it.
255	            if sub_idx == 0 {
256	                return SearchHit {
257	                    kind: HitKind::Session,
258	                    title: meta["session_name"].as_str().unwrap_or("").to_string(),
259	                    dir: super::short_path(meta["project"].as_str().unwrap_or("")),
260	                    excerpt_lines: vec![],
261	                    session_id: meta["session_id"].as_str().map(str::to_string),
262	                    repo_dir: None,
263	                    turn_id: None, hit_ts: None,
264	                    branch: meta["branch"].as_str().unwrap_or("").to_string(),
265	                    agent: String::new(), backed_up: false, updated_at: String::new(),
266	                    author: String::new(), remote: String::new(),
267	                };
268	            }
269	
270	            let name    = meta["session_name"].as_str().unwrap_or("").to_string();
271	            let project = meta["project"].as_str().unwrap_or("").to_string();
272	            let branch  = meta["branch"].as_str().unwrap_or("").to_string();
273	
274	            let mut excerpt_lines: Vec<String> = Vec::new();
275	            if sub_idx > 1 {
276	                if let Some(prev) = bodies.get(sub_idx - 1) {
277	                    let t: String = strip_user_label(prev.trim()).chars().take(220).collect();
278	                    if !t.is_empty() { excerpt_lines.push(t); }
279	                }
280	            }
281	            if let Some(matched) = bodies.get(sub_idx) {
282	                let t: String = strip_user_label(matched.trim()).chars().take(400).collect();
283	                if !t.is_empty() { excerpt_lines.push(t); }
284	            }
285	            if sub_idx + 1 < bodies.len() {
286	                if let Some(next) = bodies.get(sub_idx + 1) {
287	                    let t: String = strip_user_label(next.trim()).chars().take(220).collect();
288	                    if !t.is_empty() { excerpt_lines.push(t); }
289	                }
290	            }
291	
292	            // sub_idx 0 = header matched, 1+ = turns[sub_idx-1] matched.
293	            let turn_meta = if sub_idx > 0 { &meta["turns"][sub_idx - 1] } else { &serde_json::Value::Null };
294	            let hit_ts  = turn_meta["timestamp"].as_str().filter(|s| !s.is_empty()).map(str::to_string);
295	            let turn_id = turn_meta["uuid"].as_str().filter(|s| !s.is_empty()).map(str::to_string);
296	
297	            SearchHit {
298	                kind: HitKind::Log,
299	                title: name,
300	                dir: super::short_path(&project),
301	                excerpt_lines,
302	                session_id: meta["session_id"].as_str().map(str::to_string),
303	                repo_dir: None,
304	                turn_id,
305	                hit_ts,
306	                branch,
307	                agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
308	                remote: String::new(),
309	            }
310	        }
311	    }
312	}
