314	// ── Group building ────────────────────────────────────────────────────────────
315	
316	// Each hit becomes its own selectable group — one header row + one excerpt row.
317	// We do not merge multiple hits from the same session; that produced a wall of
318	// text that couldn't be navigated individually.
319	fn build_groups(hits: Vec<SearchHit>) -> Vec<Group> {
320	    let mut groups: Vec<Group> = Vec::new();
321	
322	    for hit in hits {
323	        match hit.kind {
324	            HitKind::Log | HitKind::Checkpoint => {
325	                let is_cp = matches!(hit.kind, HitKind::Checkpoint);
326	                groups.push(Group {
327	                    title: hit.title,
328	                    dir: hit.dir,
329	                    branch: hit.branch,
330	                    agent: hit.agent,
331	                    backed_up: hit.backed_up,
332	                    updated_at: hit.updated_at,
333	                    remote: hit.remote,
334	                    session_id: hit.session_id,
335	                    repo_dir: None,
336	                    kind: if is_cp { HitKind::Checkpoint } else { HitKind::Log },
337	                    author: hit.author,
338	                    rows: vec![GroupRow {
339	                        hit_ts: hit.hit_ts,
340	                        turn_id: hit.turn_id,
341	                        lines: hit.excerpt_lines,
342	                        is_checkpoint: is_cp,
343	                    }],
344	                });
345	            }
346	            HitKind::Session => {
347	                groups.push(Group {
348	                    title: hit.title,
349	                    dir: hit.dir,
350	                    branch: String::new(),
351	                    agent: hit.agent,
352	                    backed_up: hit.backed_up,
353	                    updated_at: hit.updated_at,
354	                    remote: hit.remote,
355	                    session_id: hit.session_id,
356	                    repo_dir: None,
357	                    kind: HitKind::Session,
358	                    author: hit.author,
359	                    rows: vec![],
360	                });
361	            }
362	            HitKind::Repo => {
363	                groups.push(Group {
364	                    title: hit.title,
365	                    dir: hit.dir,
366	                    branch: String::new(),
367	                    agent: String::new(),
368	                    backed_up: false,
369	                    updated_at: String::new(),
370	                    remote: hit.remote,
371	                    session_id: None,
372	                    repo_dir: hit.repo_dir,
373	                    kind: HitKind::Repo,
374	                    author: String::new(),
375	                    rows: vec![],
376	                });
377	            }
378	        }
379	    }
380	
381	    // Stable sort by dir so hits from the same repo cluster together while
382	    // preserving the original relevance ordering within each repo.
383	    groups.sort_by(|a, b| a.dir.cmp(&b.dir));
384	
385	    groups
386	}
