388	// ── TUI ───────────────────────────────────────────────────────────────────────
389	
390	fn tui_loop(stdout: &mut impl Write, groups: &[Group], query: &str, ms: u128) -> Result<bool> {
391	    let mut sel    = 0usize;
392	    let mut scroll = 0usize;
393	    let mut quit_app = false;
394	
395	    loop {
396	        let (w, h) = terminal::size().unwrap_or((120, 40));
397	        let w = w as usize;
398	        let h = h as usize;
399	        let content_h = h.saturating_sub(2);
400	
401	        let sel_start = group_start_of(groups, sel);
402	        let sel_end   = sel_start + groups.get(sel).map_or(1, rows_for_group);
403	        if sel_start < scroll                { scroll = sel_start; }
404	        else if sel_end > scroll + content_h { scroll = sel_end.saturating_sub(content_h); }
405	
406	        draw(stdout, groups, query, ms, sel, scroll, w, h)?;
407	
408	        match event::read()? {
409	            Event::Key(k) => match k.code {
410	                KeyCode::Char('q') => { quit_app = true; break; }
411	                KeyCode::Esc | KeyCode::Left => break,
412	                KeyCode::Char('c') if k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
413	                    execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
414	                    terminal::disable_raw_mode().ok();
415	                    std::process::exit(0);
416	                }
417	                KeyCode::Up   | KeyCode::Char('k') => { if sel > 0 { sel -= 1; } }
418	                KeyCode::Down | KeyCode::Char('j') => { if sel + 1 < groups.len() { sel += 1; } }
419	                KeyCode::Char('g') => { sel = 0; scroll = 0; }
420	                KeyCode::Char('G') => { sel = groups.len().saturating_sub(1); }
421	                KeyCode::Char(' ') | KeyCode::Right | KeyCode::Enter => {
422	                    if let Some(group) = groups.get(sel) {
423	                        execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
424	                        terminal::disable_raw_mode().ok();
425	
426	                        let nested_quit = match group.kind {
427	                            HitKind::Log | HitKind::Checkpoint | HitKind::Session => {
428	                                if let Some(id) = &group.session_id {
429	                                    let tid = group.rows.first().and_then(|r| r.turn_id.as_deref());
430	                                    let hts = group.rows.first().and_then(|r| r.hit_ts.as_deref());
431	                                    super::show::run_at(id, tid, hts).unwrap_or(false)
432	                                } else { false }
433	                            }
434	                            HitKind::Repo => {
435	                                if let Some(dir) = &group.repo_dir {
436	                                    let _ = super::status::run_for_dir(dir);
437	                                }
438	                                false
439	                            }
440	                        };
441	
442	                        if nested_quit { quit_app = true; break; }
443	
444	                        terminal::enable_raw_mode().ok();
445	                        execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
446	                        execute!(stdout, terminal::Clear(ClearType::All)).ok();
447	                    }
448	                }
449	                _ => {}
450	            },
451	            Event::Resize(_, _) => {
452	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
453	            }
454	            _ => {}
455	        }
456	    }
457	
458	    Ok(quit_app)
459	}
460	
461	fn rows_for_group(g: &Group) -> usize {
462	    1 + g.rows.iter().map(|r| r.lines.len().max(1)).sum::<usize>() + 1 // +1 for blank separator
463	}
464	
465	fn group_start_of(groups: &[Group], idx: usize) -> usize {
466	    groups[..idx.min(groups.len())].iter().map(rows_for_group).sum()
467	}
