469	// ── Rendering ─────────────────────────────────────────────────────────────────
470	
471	fn draw(
472	    stdout: &mut impl Write,
473	    groups: &[Group],
474	    query:  &str,
475	    ms:     u128,
476	    sel:    usize,
477	    scroll: usize,
478	    w:      usize,
479	    h:      usize,
480	) -> io::Result<()> {
481	    use crossterm::queue;
482	    let t = crate::theme::get();
483	    const TS_W: usize = 12; // fixed width of the timestamp column in excerpt rows
484	
485	    let content_h = h.saturating_sub(2);
486	    let mut buf: Vec<u8> = Vec::with_capacity((w + 60) * (h + 2));
487	
488	    // Title bar
489	    queue!(buf, cursor::MoveTo(0, 0), terminal::Clear(ClearType::UntilNewLine))?;
490	    let hdr = format!("  search: \"{}\"  {} result(s)  {}ms", query, groups.len(), ms);
491	    write!(buf, "\x1b[1m{}\x1b[0m", hdr.chars().take(w).collect::<String>())?;
492	
493	    // Pre-compute column widths across all groups for tabular alignment.
494	    let name_w   = groups.iter().map(|g| g.title.trim().chars().count()).max().unwrap_or(0).min(45);
495	    let agent_w  = groups.iter().map(|g| g.agent.chars().count()).max().unwrap_or(0);
496	    let author_w = groups.iter().map(|g| g.author.chars().count()).max().unwrap_or(0);
497	    let branch_w = groups.iter().map(|g| g.branch.chars().count()).max().unwrap_or(0).min(30);
498	
499	    let accent = t.accent;
500	    // Write one content line into the buffer using the ▌ bar for selection.
501	    let mut write_row = |buf: &mut Vec<u8>, line: &str, selected: bool, screen_row: usize| -> io::Result<()> {
502	        queue!(buf, cursor::MoveTo(0, screen_row as u16), terminal::Clear(ClearType::UntilNewLine))?;
503	        if selected {
504	            write!(buf, "\x1b[{accent}m▌\x1b[0m {line}")?;
505	        } else {
506	            write!(buf, "  {line}")?;
507	        }
508	        Ok(())
509	    };
510	
511	    let mut screen_row = 1usize; // next terminal row to write (row 0 is title bar)
512	    let mut abs_row    = 0usize; // absolute content row (before scroll is applied)
513	
514	    for (gi, group) in groups.iter().enumerate() {
515	        if screen_row > content_h { break; }
516	        let selected = gi == sel;
517	
518	        // ── Session header ────────────────────────────────────────────────
519	        if abs_row >= scroll && screen_row <= content_h {
520	            let age     = age_secs_hit(&group.updated_at);
521	            let dot_col = match age {
522	                a if a < 900   => t.fresh,
523	                a if a < 3_600 => t.moderate,
524	                _              => t.text_dim,
525	            };
526	            let (name_col, meta_col, dot_char) = if group.backed_up {
527	                (t.backed_name, t.backed_meta, "★")
528	            } else {
529	                (t.unbacked_name, t.unbacked_meta, "·")
530	            };
531	
532	            let name: String = group.title.trim().chars().take(name_w).collect();
533	            let name_padded  = format!("{name:<name_w$}");
534	            let mut line = format!(
535	                "\x1b[{dot_col}m{dot_char}\x1b[0m \x1b[{name_col}m{name_padded}\x1b[0m  \x1b[{dm}m{}\x1b[0m",
536	                group.dir, dm = t.text_dim,
537	            );
538	
539	            if branch_w > 0 {
540	                let branch_col = if group.backed_up { t.link } else { t.stale };
541	                let b: String = group.branch.chars().take(branch_w).collect();
542	                let pad = " ".repeat(branch_w - b.chars().count());
543	                line.push_str(&format!("  \x1b[{branch_col}m{b}{pad}\x1b[0m"));
544	            }
545	
546	            if author_w > 0 {
547	                let a: String = group.author.chars().take(author_w).collect();
548	                let pad = " ".repeat(author_w - a.chars().count());
549	                let col = super::author_color(&group.author);
550	                line.push_str(&format!("  \x1b[38;5;{col}m{a}\x1b[0m{pad}"));
551	            }
552	
553	            if agent_w > 0 {
554	                let a: String = group.agent.chars().take(agent_w).collect();
555	                let pad = " ".repeat(agent_w - a.chars().count());
556	                if group.backed_up {
557	                    let col = agent_color(&group.agent);
558	                    line.push_str(&format!("  \x1b[38;5;{col}m{a}{pad}\x1b[0m"));
559	                } else {
560	                    line.push_str(&format!("  \x1b[{st}m{a}{pad}\x1b[0m", st = t.stale));
561	                }
562	            }
563	
564	            if let Some(sid) = &group.session_id {
565	                let id_short: String = sid.chars().take(8).collect();
566	                let ts = rel_time_hit(&group.updated_at);
567	                line.push_str(&format!("  \x1b[{meta_col}m{id_short}  {ts}\x1b[0m"));
568	            } else if matches!(group.kind, HitKind::Repo) {
569	                line.push_str(&format!("  \x1b[{meta_col}mrepo\x1b[0m"));
570	            }
571	
572	            // Header row: full background highlight so the session name pops.
573	            super::render_row(&mut buf, &line, selected, screen_row, w)?;
574	            screen_row += 1;
575	        }
576	        abs_row += 1;
577	
578	        // ── Excerpt rows ──────────────────────────────────────────────────
579	        for row in &group.rows {
580	            let ts_str = row.hit_ts.as_deref().map(rel_time_hit).unwrap_or_default();
581	            let n_lines = row.lines.len().max(1);
582	            let excerpt_indent = " ".repeat(2 + TS_W + 2);
583	
584	            for li in 0..n_lines {
585	                if abs_row >= scroll && screen_row <= content_h {
586	                    let text = row.lines.get(li).map(String::as_str).unwrap_or("");
587	                    let avail = w.saturating_sub(2 + TS_W + 2);
588	
589	                    let exc_line = if li == 0 && row.is_checkpoint {
590	                        let ts_padded = format!("{ts_str:>TS_W$}");
591	                        let text_t: String = text.chars().take(avail.saturating_sub(5)).collect();
592	                        format!(
593	                            "  \x1b[{dm}m{ts_padded}\x1b[0m  \x1b[{lb}m[cp]\x1b[0m \x1b[{sc}m{text_t}\x1b[0m",
594	                            dm = t.text_dim, lb = t.label, sc = t.text_secondary,
595	                        )
596	                    } else if li == 0 {
597	                        let ts_padded = format!("{ts_str:>TS_W$}");
598	                        let text_t: String = text.chars().take(avail).collect();
599	                        format!(
600	                            "  \x1b[{dm}m{ts_padded}\x1b[0m  \x1b[{sc}m{text_t}\x1b[0m",
601	                            dm = t.text_dim, sc = t.text_secondary,
602	                        )
603	                    } else {
604	                        let text_t: String = text.chars().take(avail).collect();
605	                        format!("{excerpt_indent}\x1b[{sc}m{text_t}\x1b[0m", sc = t.text_secondary)
606	                    };
607	
608	                    // Excerpt rows: ▌ bar ties them visually to the selected header.
609	                    write_row(&mut buf, &exc_line, selected, screen_row)?;
610	                    screen_row += 1;
611	                }
612	                abs_row += 1;
613	            }
614	        }
615	
616	        // Blank separator row between groups
617	        if abs_row >= scroll && screen_row <= content_h {
618	            queue!(buf, cursor::MoveTo(0, screen_row as u16), terminal::Clear(ClearType::UntilNewLine))?;
619	            screen_row += 1;
620	        }
621	        abs_row += 1;
622	    }
623	
624	    // Clear any leftover rows below the results.
625	    while screen_row <= content_h {
626	        queue!(buf, cursor::MoveTo(0, screen_row as u16), terminal::Clear(ClearType::UntilNewLine))?;
627	        screen_row += 1;
628	    }
629	
630	    super::draw_statusbar(&mut buf, "  ↑↓/jk: navigate   space/→: open   ←/esc: back   q: quit  ", w, h)?;
631	
632	    stdout.write_all(&buf)?;
633	    stdout.flush()
634	}
