637	// ── DB enrichment ─────────────────────────────────────────────────────────────
638	
639	fn enrich_hits(hits: &mut Vec<SearchHit>) {
640	    let Ok(conn) = crate::db::connect() else { return };
641	    for hit in hits.iter_mut() {
642	        if let Some(sid) = &hit.session_id {
643	            // Pull agent + remote, plus the first checkpoint's author (matching
644	            // the resolution session_list::query_db uses: name > email > os_user).
645	            if let Ok((agent, updated_at, remote, author_name, author_email, author_os_user)) =
646	                conn.query_row(
647	                    "SELECT s.agent_name, s.updated_at, COALESCE(r.remote, ''),
648	                            COALESCE(c.author_name, ''), COALESCE(c.author_email, ''),
649	                            COALESCE(c.os_user, '')
650	                     FROM sessions s
651	                     LEFT JOIN repositories r
652	                       ON (s.cwd = r.directory OR s.cwd LIKE r.directory || '/%')
653	                     LEFT JOIN checkpoints c
654	                       ON c.session_id = s.session_id
655	                      AND c.last_turn_ts = (
656	                            SELECT MIN(last_turn_ts) FROM checkpoints
657	                            WHERE session_id = s.session_id
658	                          )
659	                     WHERE s.session_id = ?1",
660	                    [sid.as_str()],
661	                    |row| Ok((
662	                        row.get::<_, String>(0)?,
663	                        row.get::<_, String>(1)?,
664	                        row.get::<_, String>(2)?,
665	                        row.get::<_, String>(3)?,
666	                        row.get::<_, String>(4)?,
667	                        row.get::<_, String>(5)?,
668	                    )),
669	                )
670	            {
671	                hit.agent      = agent;
672	                hit.updated_at = updated_at;
673	                hit.backed_up  = true;
674	                hit.remote     = remote;
675	                hit.author     = if !author_name.trim().is_empty() { author_name }
676	                                 else if !author_email.trim().is_empty() { author_email }
677	                                 else { author_os_user };
678	            }
679	        } else if let Some(dir) = &hit.repo_dir.clone() {
680	            if let Ok(remote) = conn.query_row(
681	                "SELECT COALESCE(remote, '') FROM repositories WHERE directory = ?1",
682	                [dir.as_str()],
683	                |row| row.get::<_, String>(0),
684	            ) {
685	                hit.remote = remote;
686	            }
687	        }
688	    }
689	}
690	
691	// ── Direct name search ────────────────────────────────────────────────────────
692	
693	fn search_sessions_by_name(query: &str) -> Vec<SearchHit> {
694	    let words: Vec<String> = query.split_whitespace().map(|w| w.to_lowercase()).collect();
695	    if words.is_empty() { return vec![]; }
696	
697	    let Ok(conn) = crate::db::connect() else { return vec![]; };
698	    let Ok(mut stmt) = conn.prepare(
699	        "SELECT session_id, session_name, cwd FROM sessions WHERE session_name != ''"
700	    ) else { return vec![]; };
701	
702	    stmt.query_map([], |row| Ok((row.get::<_,String>(0)?, row.get::<_,String>(1)?, row.get::<_,String>(2)?)))
703	        .ok()
704	        .into_iter()
705	        .flatten()
706	        .flatten()
707	        .filter_map(|(session_id, session_name, cwd): (String, String, String)| {
708	            let normalized = session_name.to_lowercase().replace(['-', '_'], " ");
709	            if words.iter().all(|w| normalized.contains(w.as_str())) {
710	                Some(SearchHit {
711	                    kind: HitKind::Session,
712	                    title: session_name,
713	                    dir: super::short_path(&cwd),
714	                    excerpt_lines: vec![],
715	                    session_id: Some(session_id),
716	                    repo_dir: None,
717	                    turn_id: None, hit_ts: None, branch: String::new(),
718	                    agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
719	                    remote: String::new(),
720	                })
721	            } else {
722	                None
723	            }
724	        })
725	        .collect()
726	}
727	
728	fn search_repos_by_name(query: &str) -> Vec<SearchHit> {
729	    let words: Vec<String> = query.split_whitespace().map(|w| w.to_lowercase()).collect();
730	    if words.is_empty() { return vec![]; }
731	
732	    let Ok(conn) = crate::db::connect() else { return vec![]; };
733	    let Ok(mut stmt) = conn.prepare(
734	        "SELECT name, directory, COALESCE(remote, '') FROM repositories WHERE name != ''"
735	    ) else { return vec![]; };
736	
737	    stmt.query_map([], |row| Ok((row.get::<_,String>(0)?, row.get::<_,String>(1)?, row.get::<_,String>(2)?)))
738	        .ok()
739	        .into_iter()
740	        .flatten()
741	        .flatten()
742	        .filter_map(|(name, directory, remote): (String, String, String)| {
743	            let normalized = name.to_lowercase().replace(['-', '_'], " ");
744	            if words.iter().all(|w| normalized.contains(w.as_str())) {
745	                Some(SearchHit {
746	                    kind: HitKind::Repo,
747	                    title: name,
748	                    dir: super::short_path(&directory),
749	                    excerpt_lines: vec![],
750	                    session_id: None,
751	                    repo_dir: Some(directory),
752	                    turn_id: None, hit_ts: None, branch: String::new(),
753	                    agent: String::new(), backed_up: false, updated_at: String::new(), author: String::new(),
754	                    remote,
755	                })
756	            } else {
757	                None
758	            }
759	        })
760	        .collect()
761	}
762	
763	// ── Helpers ───────────────────────────────────────────────────────────────────
764	
765	fn rel_time_hit(iso: &str) -> String {
766	    if iso.is_empty() { return String::new(); }
767	    let Ok(dt) = DateTime::parse_from_rfc3339(iso) else { return String::new(); };
768	    let secs = (Utc::now() - dt.with_timezone(&Utc)).num_seconds().max(0);
769	    if secs < 604_800 {
770	        match secs {
771	            s if s < 60     => "just now".into(),
772	            s if s < 3_600  => format!("{} min ago", s / 60),
773	            s if s < 86_400 => format!("{} hr ago",  s / 3_600),
774	            s               => format!("{} day{} ago", s / 86_400, if s / 86_400 == 1 { "" } else { "s" }),
775	        }
776	    } else {
777	        dt.with_timezone(&chrono::Local).format("%m/%d/%y").to_string()
778	    }
779	}
780	
781	fn age_secs_hit(iso: &str) -> i64 {
782	    if iso.is_empty() { return i64::MAX; }
783	    let Ok(dt) = DateTime::parse_from_rfc3339(iso) else { return i64::MAX; };
784	    (Utc::now() - dt.with_timezone(&Utc)).num_seconds().max(0)
785	}
