300	    let Ok(conn) = crate::db::connect() else { return Vec::new(); };
301	    let Ok(mut stmt) = conn.prepare(
302	        "SELECT checkpoint_id,
303	                COALESCE(commit_sha, ''),
304	                COALESCE(repo_dir, ''),
305	                COALESCE(commit_message, ''),
306	                last_turn_ts,
307	                COALESCE(author_name, ''),
308	                COALESCE(author_email, ''),
309	                COALESCE(files_touched, '[]'),
310	                COALESCE(token_usage, ''),
311	                COALESCE(initial_attribution, ''),
312	                COALESCE(model, '')
313	           FROM checkpoints
314	          WHERE session_id = ?1
315	       ORDER BY last_turn_ts ASC"
316	    ) else { return Vec::new(); };
317	
318	    let rows = stmt.query_map([session_id], |row| {
319	        Ok((
320	            row.get::<_, String>(0)?,
321	            row.get::<_, String>(1)?,
322	            row.get::<_, String>(2)?,
323	            row.get::<_, String>(3)?,
324	            row.get::<_, String>(4)?,
325	            row.get::<_, String>(5)?,
326	            row.get::<_, String>(6)?,
327	            row.get::<_, String>(7)?,
328	            row.get::<_, String>(8)?,
329	            row.get::<_, String>(9)?,
330	            row.get::<_, String>(10)?,
331	        ))
332	    });
333	    let Ok(rows) = rows else { return Vec::new(); };
334	
335	    let mut out = Vec::new();
336	    for (seq, r) in rows.flatten().enumerate() {
337	        let (checkpoint_id, commit_sha, repo_dir, commit_message, last_turn_ts,
338	             author_name, author_email, files_json, token_json, attr_json, model) = r;
339	        let number = (seq + 1) as u32;
340	
341	        let files_touched: Vec<String> = serde_json::from_str(&files_json).unwrap_or_default();
342	
343	        let token_usage = serde_json::from_str::<serde_json::Value>(&token_json).ok()
344	            .and_then(|v| {
