348	                    cache_read_tokens:     v["cache_read_tokens"].as_i64().unwrap_or(0),
349	                    output_tokens:         v["output_tokens"].as_i64().unwrap_or(0),
350	                    api_call_count:        v["api_call_count"].as_i64().unwrap_or(0),
351	                })
352	            });
353	
354	        let initial_attribution = serde_json::from_str::<serde_json::Value>(&attr_json).ok()
355	            .and_then(|v| {
356	                Some(InitialAttribution {
357	                    human_added:         v["human_added"].as_i64().unwrap_or(0),
358	                    human_modified:      v["human_modified"].as_i64().unwrap_or(0),
359	                    human_removed:       v["human_removed"].as_i64().unwrap_or(0),
360	                    total_committed:     v["total_committed"].as_i64().unwrap_or(0),
361	                    total_lines_changed: v["total_lines_changed"].as_i64().unwrap_or(0),
362	                    agent_percentage:    v["agent_percentage"].as_f64().unwrap_or(0.0),
363	                })
364	            });
365	
366	        out.push(CheckpointData {
367	            number: number as u32,
368	            checkpoint_id,
369	            commit_sha,
370	            repo_dir,
371	            commit_message,
372	            last_turn_ts,
373	            author_name,
374	            author_email,
375	            files_touched,
376	            token_usage,
377	            initial_attribution,
378	            model,
379	        });
380	    }
381	    out
382	}
