384	fn card_ts(card: &Card) -> Option<&str> {
385	    match card {
386	        Card::UserMsg { ts, .. } | Card::AsstMsg { ts, .. } | Card::System { ts, .. } => Some(ts),
387	        _ => None,
388	    }
389	}
390	
391	fn insert_checkpoints(cards: &mut Vec<Card>, checkpoints: Vec<CheckpointData>) {
392	    // Process in reverse so earlier insertions don't shift later positions.
393	    for cp in checkpoints.into_iter().rev() {
394	        // Find the last card whose timestamp is ≤ this checkpoint's last turn.
395	        let pos = cards.iter().rposition(|c| {
396	            card_ts(c).map_or(false, |ts| ts <= cp.last_turn_ts.as_str())
397	        });
398	        let mut insert_at = pos.map(|i| i + 1).unwrap_or(cards.len());
399	        // Advance past ToolRound cards and any AsstMsg cards (away summary) that
400	        // belong to the same turn — they have no timestamp or a ts ≤ last_turn_ts.
401	        while insert_at < cards.len() {
402	            match &cards[insert_at] {
403	                Card::ToolRound { .. } => { insert_at += 1; }
404	                Card::AsstMsg { ts, .. } if ts.as_str() <= cp.last_turn_ts.as_str() => { insert_at += 1; }
405	                _ => break,
406	            }
407	        }
408	        cards.insert(insert_at, Card::Checkpoint(cp));
409	    }
410	}
