412	fn find_session(id: &str) -> Option<PathBuf> {
413	    let p = PathBuf::from(id);
414	    if p.exists() { return Some(p); }
415	    if let Ok(home) = std::env::var("HOME") {
416	        let projects = PathBuf::from(&home).join(".claude/projects");
417	        if let Ok(entries) = std::fs::read_dir(&projects) {
418	            for entry in entries.flatten() {
419	                let candidate = entry.path().join(format!("{id}.jsonl"));
420	                if candidate.exists() { return Some(candidate); }
421	            }
422	        }
423	    }
424	    // Fall back to extracting the latest checkpoint's full.jsonl from the
425	    // entire/checkpoints/v1 branch. Used when this session was authored on
426	    // another machine and never produced a local Claude Code log.
427	    extract_from_checkpoint(id)
428	}
429	
430	fn extract_from_checkpoint(session_id: &str) -> Option<PathBuf> {
431	    let conn = crate::db::connect().ok()?;
432	    let jsonl_path: String = conn.query_row(
433	        "SELECT jsonl_path FROM checkpoints
434	         WHERE session_id = ?1
435	           AND jsonl_path IS NOT NULL
436	         ORDER BY last_turn_ts DESC
437	         LIMIT 1",
438	        [session_id],
439	        |row| row.get(0),
440	    ).ok()?;
441	
442	    // The stored `repo_dir` is whichever repo's index pass last wrote this
443	    // checkpoint row — sometimes stale (the file may since have been removed
444	    // from that repo's branch, or the same file lives in multiple repos'
445	    // shared checkpoint branch). Try the recorded repo_dir first, then fall
446	    // back to every other tracked repo. Whichever clone actually has the path
447	    // in its checkpoint branch wins.
448	    let preferred: Option<String> = conn.query_row(
449	        "SELECT repo_dir FROM checkpoints
450	         WHERE session_id = ?1 AND repo_dir IS NOT NULL
451	         ORDER BY last_turn_ts DESC LIMIT 1",
452	        [session_id], |row| row.get(0),
453	    ).ok();
454	
455	    let mut candidates: Vec<String> = Vec::new();
456	    if let Some(p) = preferred { candidates.push(p); }
457	    if let Ok(mut stmt) = conn.prepare("SELECT directory FROM repositories") {
458	        if let Ok(rows) = stmt.query_map([], |row| row.get::<_, String>(0)) {
459	            for r in rows.flatten() {
460	                if !candidates.contains(&r) { candidates.push(r); }
461	            }
462	        }
463	    }
464	
465	    let bytes = candidates.iter()
466	        .find_map(|dir| crate::commands::index::git_show(dir, &jsonl_path).ok())?;
467	
468	    let home = std::env::var("HOME").ok()?;
469	    let cache_dir = PathBuf::from(&home).join(".gossamer").join("sessions");
470	    std::fs::create_dir_all(&cache_dir).ok()?;
471	    let cache_path = cache_dir.join(format!("{session_id}.jsonl"));
472	    std::fs::write(&cache_path, &bytes).ok()?;
473	    Some(cache_path)
474	}
