476	// ── Parsing ───────────────────────────────────────────────────────────────────
477	
478	fn parse(raw: &str, agent: &str) -> Vec<Card> {
479	    let mut tool_names: HashMap<String, String> = HashMap::new();
480	    for line in raw.lines() {
481	        if let Ok(v) = serde_json::from_str::<Value>(line) {
482	            if let Some(blocks) = v["message"]["content"].as_array() {
483	                for b in blocks {
484	                    if b["type"].as_str() == Some("tool_use") {
485	                        if let (Some(id), Some(name)) = (b["id"].as_str(), b["name"].as_str()) {
486	                            tool_names.insert(id.to_string(), name.to_string());
487	                        }
488	                    }
489	                }
490	            }
491	        }
492	    }
493	
494	    let mut cards: Vec<Card> = Vec::new();
495	    let mut first_cwd    = String::new();
496	    let mut first_branch = String::new();
497	    let mut first_ts     = String::new();
498	    let mut title: Option<String> = None;
499	
500	    for line in raw.lines() {
501	        if line.trim().is_empty() { continue; }
502	        let Ok(v) = serde_json::from_str::<Value>(line) else { continue };
503	        let ts = v["timestamp"].as_str().unwrap_or("").to_string();
504	        if first_ts.is_empty() && !ts.is_empty() { first_ts = ts.clone(); }
505	
506	        match v["type"].as_str() {
507	            Some("custom-title") => {
508	                title = v["customTitle"].as_str().map(str::to_string);
509	            }
510	            Some("system") => {
511	                if let Some(c) = v["cwd"].as_str() { if first_cwd.is_empty() { first_cwd = c.to_string(); } }
512	                let content = v["content"].as_str().unwrap_or("").to_string();
513	                if !content.is_empty() {
514	                    let subtype = v["subtype"].as_str().unwrap_or("system").replace('_', " ");
515	                    cards.push(Card::System { ts, subtype, content });
516	                }
517	            }
518	            Some("user") => {
519	                if let Some(c) = v["cwd"].as_str()       { if first_cwd.is_empty()    { first_cwd    = c.to_string(); } }
520	                if let Some(b) = v["gitBranch"].as_str() { if first_branch.is_empty() { first_branch = b.to_string(); } }
521	                let parts = parse_user(&v["message"]["content"], &tool_names);
522	                if !parts.is_empty() { cards.push(Card::UserMsg { ts, parts, author: None }); }
523	            }
524	            Some("assistant") => {
525	                let parts = parse_asst(&v["message"]["content"]);
526	                if !parts.is_empty() { cards.push(Card::AsstMsg { ts, parts }); }
527	            }
528	            _ => {}
529	        }
530	    }
531	
532	    let mut result = vec![Card::Header { title, cwd: first_cwd, branch: first_branch, ts: first_ts, agent: agent.to_string() }];
533	    result.extend(cards);
534	
535	    // Merge each pure tool-result UserMsg into the preceding AsstMsg.
536	    let mut i = 1;
537	    while i < result.len() {
538	        let is_pure_results = if let Card::UserMsg { parts, .. } = &result[i] {
539	            parts.iter().all(|p| matches!(p, UserPart::ToolResult { .. }))
540	        } else { false };
541	
542	        if is_pure_results && matches!(&result[i - 1], Card::AsstMsg { .. }) {
543	            let tool_results: Vec<(String, String, bool)> =
544	                if let Card::UserMsg { parts, .. } = &result[i] {
545	                    parts.iter().filter_map(|p| {
546	                        if let UserPart::ToolResult { id, content, is_error, .. } = p {
547	                            Some((id.clone(), content.clone(), *is_error))
548	                        } else { None }
549	                    }).collect()
550	                } else { vec![] };
551	
552	            if let Card::AsstMsg { parts: asst_parts, .. } = &mut result[i - 1] {
553	                for part in asst_parts.iter_mut() {
554	                    if let AsstPart::ToolCall { id, result: res, .. } = part {
555	                        if let Some((_, content, is_error)) =
556	                            tool_results.iter().find(|(rid, _, _)| rid == id)
557	                        {
558	                            *res = Some((content.clone(), *is_error));
559	                        }
560	                    }
561	                }
562	            }
563	            result.remove(i);
564	        } else {
565	            i += 1;
566	        }
567	    }
568	
569	    // Merge consecutive AsstMsg cards so the assistant name appears only once per run.
570	    let mut i = 1;
571	    while i < result.len() {
572	        if matches!(&result[i - 1], Card::AsstMsg { .. }) && matches!(&result[i], Card::AsstMsg { .. }) {
573	            if let Card::AsstMsg { parts: new_parts, .. } = result.remove(i) {
574	                if let Card::AsstMsg { parts, .. } = &mut result[i - 1] {
575	                    parts.extend(new_parts);
576	                }
577	            }
578	        } else {
579	            i += 1;
580	        }
581	    }
582	
583	    // Split each AsstMsg into a text-only AsstMsg (if any text) + a ToolRound (if any tools).
584	    let mut split: Vec<Card> = Vec::with_capacity(result.len());
585	    for card in result {
586	        match card {
587	            Card::AsstMsg { ts, parts } => {
588	                let (text_parts, tool_parts): (Vec<AsstPart>, Vec<AsstPart>) =
589	                    parts.into_iter().partition(|p| matches!(p, AsstPart::Text(_)));
590	                if !text_parts.is_empty() { split.push(Card::AsstMsg  { ts, parts: text_parts }); }
591	                if !tool_parts.is_empty() { split.push(Card::ToolRound { parts: tool_parts }); }
592	            }
593	            other => split.push(other),
594	        }
595	    }
596	    let mut result = split;
597	
598	    // Merge adjacent ToolRound cards (can arise when consecutive asst turns were all-tools).
599	    let mut i = 1;
600	    while i < result.len() {
601	        if matches!(&result[i - 1], Card::ToolRound { .. }) && matches!(&result[i], Card::ToolRound { .. }) {
602	            if let Card::ToolRound { parts: new_parts } = result.remove(i) {
603	                if let Card::ToolRound { parts } = &mut result[i - 1] {
604	                    parts.extend(new_parts);
605	                }
606	            }
607	        } else {
608	            i += 1;
609	        }
610	    }
611	
612	    result
613	}
614	
615	fn parse_user(content: &Value, tool_names: &HashMap<String, String>) -> Vec<UserPart> {
616	    let mut out = Vec::new();
617	    match content {
618	        Value::String(s) if !s.trim().is_empty() => out.push(UserPart::Text(s.clone())),
619	        Value::Array(blocks) => {
620	            for b in blocks {
621	                match b["type"].as_str() {
622	                    Some("text") => {
623	                        if let Some(t) = b["text"].as_str() {
624	                            if !t.trim().is_empty() { out.push(UserPart::Text(t.to_string())); }
625	                        }
626	                    }
627	                    Some("tool_result") => {
628	                        let id = b["tool_use_id"].as_str().unwrap_or("").to_string();
629	                        let name = tool_names.get(&id).cloned().unwrap_or_else(|| "tool".to_string());
630	                        let is_error = b["is_error"].as_bool().unwrap_or(false);
631	                        let content = match &b["content"] {
632	                            Value::String(s) => s.clone(),
633	                            Value::Array(arr) => arr.iter()
634	                                .filter(|x| x["type"].as_str() == Some("text"))
635	                                .filter_map(|x| x["text"].as_str())
636	                                .collect::<Vec<_>>().join("\n"),
637	                            _ => String::new(),
638	                        };
639	                        out.push(UserPart::ToolResult { id, name, content, is_error });
640	                    }
641	                    _ => {}
642	                }
643	            }
644	        }
645	        _ => {}
646	    }
647	    out
648	}
649	
650	fn parse_asst(content: &Value) -> Vec<AsstPart> {
651	    let mut out = Vec::new();
652	    match content {
653	        Value::String(s) if !s.trim().is_empty() => out.push(AsstPart::Text(s.clone())),
654	        Value::Array(blocks) => {
655	            for b in blocks {
656	                match b["type"].as_str() {
657	                    Some("text") => {
658	                        if let Some(t) = b["text"].as_str() {
659	                            if !t.trim().is_empty() { out.push(AsstPart::Text(t.to_string())); }
660	                        }
661	                    }
662	                    Some("tool_use") => {
663	                        out.push(AsstPart::ToolCall {
664	                            id:     b["id"].as_str().unwrap_or("").to_string(),
665	                            name:   b["name"].as_str().unwrap_or("unknown").to_string(),
666	                            input:  b["input"].clone(),
667	                            result: None,
668	                        });
669	                    }
670	                    _ => {}
671	                }
672	            }
673	        }
674	        _ => {}
675	    }
676	    out
677	}
