679	// ── Text extraction (for clipboard) ──────────────────────────────────────────
680	
681	fn card_text(card: &Card) -> String {
682	    let mut out = String::new();
683	    match card {
684	        Card::RepoLink { name, dir, branch } => {
685	            out.push_str(name); out.push('\n');
686	            out.push_str(dir);  out.push('\n');
687	            if !branch.is_empty() { out.push_str(branch); out.push('\n'); }
688	        }
689	        Card::Header { title, cwd, branch, agent, .. } => {
690	            if let Some(t) = title { out.push_str(t); out.push('\n'); }
691	            if !cwd.is_empty()    { out.push_str(cwd);               out.push('\n'); }
692	            if !branch.is_empty() { out.push_str(&format!("[{branch}]")); out.push('\n'); }
693	            if !agent.is_empty()  { out.push_str(agent); out.push('\n'); }
694	        }
695	        Card::System { content, .. } => { if !content.is_empty() { out.push_str(content); out.push('\n'); } }
696	        Card::UserMsg { parts, .. } => {
697	            for part in parts {
698	                match part {
699	                    UserPart::Text(t) => { out.push_str(t); out.push('\n'); }
700	                    UserPart::ToolResult { name, content, .. } => {
701	                        out.push_str(&format!("[Result: {name}]\n{content}\n"));
702	                    }
703	                }
704	            }
705	        }
706	        Card::AsstMsg { parts, .. } => {
707	            for part in parts {
708	                if let AsstPart::Text(t) = part { out.push_str(t); out.push('\n'); }
709	            }
710	        }
711	        Card::ToolRound { parts } => {
712	            for part in parts {
713	                if let AsstPart::ToolCall { name, input, result, .. } = part {
714	                    out.push_str(&format!("[Tool: {name}]\n"));
715	                    if let Some(obj) = input.as_object() {
716	                        for (k, v) in obj {
717	                            let val = if let Value::String(s) = v { s.clone() } else { v.to_string() };
718	                            out.push_str(&format!("{k}: {val}\n"));
719	                        }
720	                    }
721	                    if let Some((content, _)) = result {
722	                        out.push_str(&format!("[Result]\n{content}\n"));
723	                    }
724	                }
725	            }
726	        }
727	        Card::Checkpoint(cp) => {
728	            out.push_str(&format!("[Checkpoint #{}]\n", cp.number));
729	            if !cp.checkpoint_id.is_empty() { out.push_str(&format!("{}\n", cp.checkpoint_id)); }
730	            if !cp.commit_message.is_empty() { out.push_str(&cp.commit_message); out.push('\n'); }
731	            if !cp.files_touched.is_empty() {
732	                out.push_str("Files:\n");
733	                for f in &cp.files_touched { out.push_str(&format!("  {f}\n")); }
734	            }
735	        }
736	    }
737	    out
738	}
739	
740	fn tool_call_text(part: &AsstPart) -> String {
741	    let mut out = String::new();
742	    if let AsstPart::ToolCall { name, input, result, .. } = part {
743	        out.push_str(&format!("[Tool: {name}]\n"));
744	        if let Some(obj) = input.as_object() {
745	            for (k, v) in obj {
746	                let val = if let Value::String(s) = v { s.clone() } else { v.to_string() };
747	                out.push_str(&format!("{k}: {val}\n"));
748	            }
749	        }
750	        if let Some((content, _)) = result { out.push_str(&format!("[Result]\n{content}\n")); }
751	    }
752	    out
753	}
