755	fn copy_to_clipboard(text: &str) {
756	    use std::io::Write as _;
757	    use std::process::{Command, Stdio};
758	    if let Ok(mut child) = Command::new("pbcopy").stdin(Stdio::piped()).spawn() {
759	        if let Some(stdin) = child.stdin.take() {
760	            let mut stdin = stdin;
761	            let _ = stdin.write_all(text.as_bytes());
762	        }
763	        let _ = child.wait();
764	    }
765	}
