796	fn render_md(text: &str, width: usize) -> Vec<String> {
797	    let rendered = format!("{}", md_skin().text(text, Some(width)));
798	    // termimad appends a trailing newline; drop it to avoid spurious blank lines
799	    let trimmed = rendered.trim_end_matches('\n');
800	    trimmed.lines().map(str::to_string).collect()
801	}
