807	fn visible_width(s: &str) -> usize {
808	    let mut w = 0usize;
809	    let mut chars = s.chars().peekable();
810	    while let Some(c) = chars.next() {
811	        if c == '\x1b' {
812	            for nc in chars.by_ref() {
813	                if nc.is_ascii_alphabetic() { break; }
814	            }
815	        } else {
816	            w += 1;
817	        }
818	    }
819	    w
820	}
