822	fn fmt_num(n: i64) -> String {
823	    let s = n.abs().to_string();
824	    let mut out = String::new();
825	    for (i, ch) in s.chars().rev().enumerate() {
826	        if i > 0 && i % 3 == 0 { out.push(','); }
827	        out.push(ch);
828	    }
829	    if n < 0 { out.push('-'); }
830	    out.chars().rev().collect()
831	}
