925	/// Find the git repo directory that contains `commit_sha`, trying `preferred`
926	/// first, then falling back to all registered gossamer repos.
927	fn resolve_repo_for_commit(commit_sha: &str, preferred: &str) -> Option<String> {
928	    use std::process::Command;
929	    let has_commit = |dir: &str| {
930	        Command::new("git").args(["cat-file", "-t", commit_sha])
931	            .current_dir(dir).output()
932	            .map(|o| o.status.success()).unwrap_or(false)
933	    };
934	    if !preferred.is_empty() && std::path::Path::new(preferred).exists() && has_commit(preferred) {
935	        return Some(preferred.to_string());
936	    }
937	    let Ok(conn) = crate::db::connect() else { return None; };
938	    let Ok(mut stmt) = conn.prepare("SELECT directory FROM repositories") else { return None; };
939	    let dirs: Vec<String> = stmt.query_map([], |r| r.get(0))
940	        .map(|rs| rs.flatten().collect()).unwrap_or_default();
941	    for dir in dirs {
942	        if has_commit(&dir) { return Some(dir); }
943	    }
944	    None
945	}
