947	/// Fetch the diff for `file` in `commit_sha`, colorised with ANSI SGR.
948	fn fetch_file_diff(commit_sha: &str, repo_dir: &str, file: &str) -> Vec<String> {
949	    use std::process::Command;
950	    let t = crate::theme::get();
951	    if commit_sha.is_empty() {
952	        return vec![format!("      \x1b[{ft}m(no commit SHA available)\x1b[0m", ft = t.text_faint)];
953	    }
954	    let Some(actual_dir) = resolve_repo_for_commit(commit_sha, repo_dir) else {
955	        return vec![format!("      \x1b[{ft}m(commit not found in any registered repo)\x1b[0m", ft = t.text_faint)];
956	    };
957	    let out = Command::new("git")
958	        .args(["show", commit_sha, "--", file])
959	        .current_dir(&actual_dir)
960	        .output();
961	    let Ok(out) = out else {
962	        return vec![format!("      \x1b[{ft}m(could not run git show)\x1b[0m", ft = t.text_faint)];
963	    };
964	    let raw = String::from_utf8_lossy(&out.stdout);
965	    let mut lines: Vec<String> = Vec::new();
966	    let mut in_hunk = false;
967	    for line in raw.lines() {
968	        if line.starts_with("@@") { in_hunk = true; }
969	        if !in_hunk { continue; }
970	        let colored = if line.starts_with('+') && !line.starts_with("+++") {
971	            format!("      \x1b[{c}m{line}\x1b[0m", c = t.fresh)
972	        } else if line.starts_with('-') && !line.starts_with("---") {
973	            format!("      \x1b[{c}m{line}\x1b[0m", c = t.error)
974	        } else if line.starts_with("@@") {
975	            format!("      \x1b[{c}m{line}\x1b[0m", c = t.label)
976	        } else {
977	            format!("      \x1b[{c}m{line}\x1b[0m", c = t.text_dim)
978	        };
979	        lines.push(colored);
980	        if lines.len() >= 300 {
981	            lines.push(format!("      \x1b[{ft}m… truncated\x1b[0m", ft = t.text_faint));
982	            break;
983	        }
984	    }
985	    if lines.is_empty() {
986	        lines.push(format!("      \x1b[{ft}m(empty diff)\x1b[0m", ft = t.text_faint));
987	    }
988	    lines
989	}
