1176	fn xml_root_tag(text: &str) -> &str {
1177	    let t = text.trim_start();
1178	    let inner = t.strip_prefix('<').unwrap_or(t);
1179	    let inner = inner.trim_start_matches(['!', '/']);
1180	    let end = inner.find(|c: char| c == '>' || c == ' ' || c == '\n').unwrap_or(inner.len());
1181	    let tag = &inner[..end];
1182	    if tag.is_empty() { "xml" } else { tag }
1183	}
1184	
1185	fn strip_xml_tags(text: &str) -> String {
1186	    let mut out = String::new();
1187	    let mut in_tag = false;
1188	    for c in text.chars() {
1189	        match c {
1190	            '<' => { in_tag = true; }
1191	            '>' => { in_tag = false; }
1192	            '\n' if in_tag => {}
1193	            _ if !in_tag => out.push(c),
1194	            _ => {}
1195	        }
1196	    }
1197	    out
1198	}
