1200	fn wrap(text: &str, width: usize) -> Vec<String> {
1201	    if width < 4 { return text.lines().map(str::to_string).collect(); }
1202	    let mut out = Vec::new();
1203	    for raw_line in text.lines() {
1204	        if raw_line.is_empty() { out.push(String::new()); continue; }
1205	        let mut remaining = raw_line;
1206	        loop {
1207	            if remaining.chars().count() <= width {
1208	                out.push(remaining.to_string());
1209	                break;
1210	            }
1211	            let break_pos = remaining.chars().take(width)
1212	                .collect::<String>()
1213	                .rfind(' ')
1214	                .unwrap_or(width);
1215	            let byte_pos = remaining.char_indices().nth(break_pos)
1216	                .map(|(i, _)| i)
1217	                .unwrap_or(remaining.len());
1218	            out.push(remaining[..byte_pos].to_string());
1219	            remaining = remaining[byte_pos..].trim_start_matches(' ');
1220	        }
1221	    }
1222	    out
1223	}
