1225	fn rel_time(iso: &str) -> String {
1226	    let Ok(dt) = DateTime::parse_from_rfc3339(iso) else { return iso.to_string(); };
1227	    let secs = (Utc::now() - dt.with_timezone(&Utc)).num_seconds().max(0);
1228	    if secs < 604_800 {
1229	        match secs {
1230	            s if s < 60     => "just now".into(),
1231	            s if s < 3_600  => format!("{} min{} ago", s/60,     if s/60==1     {""} else {"s"}),
1232	            s if s < 86_400 => format!("{} hr{} ago",  s/3_600,  if s/3_600==1  {""} else {"s"}),
1233	            s               => format!("{} day{} ago", s/86_400, if s/86_400==1 {""} else {"s"}),
1234	        }
1235	    } else {
1236	        dt.with_timezone(&Local).format("%m/%d/%y").to_string()
1237	    }
1238	}
