1242	fn git_current_branch(cwd: &str) -> Option<String> {
1243	    let out = std::process::Command::new("git")
1244	        .args(["rev-parse", "--abbrev-ref", "HEAD"])
1245	        .current_dir(cwd)
1246	        .output()
1247	        .ok()?;
1248	    if !out.status.success() { return None; }
1249	    let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
1250	    if s.is_empty() || s == "HEAD" { None } else { Some(s) }
1251	}
