1253	fn create_resume_worktree(cwd: &str, branch: &str) -> Option<String> {
1254	    let root_out = std::process::Command::new("git")
1255	        .args(["rev-parse", "--show-toplevel"])
1256	        .current_dir(cwd)
1257	        .output()
1258	        .ok()?;
1259	    if !root_out.status.success() { return None; }
1260	    let repo_root = String::from_utf8_lossy(&root_out.stdout).trim().to_string();
1261	
1262	    let repo_path = std::path::Path::new(&repo_root);
1263	    let parent = repo_path.parent()?;
1264	    let repo_name = repo_path.file_name()?.to_str()?;
1265	    let wt_path = parent.join(format!("{repo_name}-{branch}"));
1266	
1267	    // Branch already exists; add a worktree pointing at it.
1268	    let _ = std::process::Command::new("git")
1269	        .args(["worktree", "add", wt_path.to_str()?, branch])
1270	        .current_dir(&repo_root)
1271	        .output();
1272	
1273	    if wt_path.exists() { Some(wt_path.to_string_lossy().to_string()) } else { None }
1274	}
