1276	fn resume_via_entire(dir: &str, branch: &str) {
1277	    use std::os::unix::process::CommandExt;
1278	
1279	    let launch_dir = if !branch.is_empty() {
1280	        let current = git_current_branch(dir);
1281	        if current.as_deref() != Some(branch) {
1282	            create_resume_worktree(dir, branch).unwrap_or_else(|| dir.to_string())
1283	        } else {
1284	            dir.to_string()
1285	        }
1286	    } else {
1287	        dir.to_string()
1288	    };
1289	
1290	    let mut entire = std::process::Command::new("entire");
1291	    entire.args(["session", "resume"]).current_dir(&launch_dir);
1292	    if !branch.is_empty() { entire.arg(branch); }
1293	
1294	    let Ok(out) = entire.output() else { eprintln!("entire session resume failed"); return; };
1295	
1296	    let cmd_str = String::from_utf8_lossy(&out.stdout).trim().to_string();
1297	    if cmd_str.is_empty() { eprintln!("entire resume returned no command"); return; }
1298	
1299	    let mut parts = cmd_str.split_whitespace();
1300	    let Some(prog) = parts.next() else { return; };
1301	    let args: Vec<&str> = parts.collect();
1302	    let err = std::process::Command::new(prog).args(&args).current_dir(&launch_dir).exec();
1303	    eprintln!("exec failed: {err}");
1304	}
