1306	/// Find a Claude session by ID. Returns `(cwd, git_branch)` from the JSONL if found,
1307	/// so `claude --resume` can be run from the correct directory and branch is known.
1308	fn find_claude_session_cwd(session_id: &str) -> Option<(String, String)> {
1309	    use std::io::BufRead;
1310	    let home = std::env::var("HOME").ok()?;
1311	    let projects = std::path::PathBuf::from(&home).join(".claude/projects");
1312	    for dir in std::fs::read_dir(&projects).ok()?.flatten() {
1313	        let jsonl = dir.path().join(format!("{session_id}.jsonl"));
1314	        if !jsonl.exists() { continue; }
1315	        let Ok(file) = std::fs::File::open(&jsonl) else { return Some((String::new(), String::new())); };
1316	        let mut cwd = String::new();
1317	        let mut branch = String::new();
1318	        for line in std::io::BufReader::new(file).lines().flatten() {
1319	            let Ok(v) = serde_json::from_str::<serde_json::Value>(&line) else { continue };
1320	            if matches!(v["type"].as_str(), Some("user") | Some("system")) {
1321	                if cwd.is_empty() {
1322	                    if let Some(c) = v["cwd"].as_str() { cwd = c.to_string(); }
1323	                }
1324	                if branch.is_empty() {
1325	                    if let Some(b) = v["gitBranch"].as_str() { branch = b.to_string(); }
1326	                }
1327	                if !cwd.is_empty() && !branch.is_empty() { break; }
1328	            }
1329	        }
1330	        return Some((cwd, branch));
1331	    }
1332	    None
1333	}
