1335	fn do_resume(_agent: &str, session_id: &str, session_branch: &str, session_cwd: &str) {
1336	    let current = git_current_branch(session_cwd);
1337	    let same_branch = !session_branch.is_empty()
1338	        && current.as_deref() == Some(session_branch);
1339	
1340	    let dir = if same_branch || session_branch.is_empty() {
1341	        session_cwd.to_string()
1342	    } else {
1343	        create_resume_worktree(session_cwd, session_branch)
1344	            .unwrap_or_else(|| session_cwd.to_string())
1345	    };
1346	
1347	    resume_session(session_id, &dir);
1348	}
