1350	/// Resume a session by ID, falling back to `entire resume` if the Claude JSONL is absent.
1351	/// `fallback_cwd` is used for `entire resume` if the Claude session isn't found.
1352	pub fn resume_session(session_id: &str, fallback_cwd: &str) {
1353	    use std::os::unix::process::CommandExt;
1354	    if let Some((session_cwd, session_branch)) = find_claude_session_cwd(session_id) {
1355	        let launch_dir = if session_cwd.is_empty() || !std::path::Path::new(&session_cwd).exists() {
1356	            fallback_cwd.to_string()
1357	        } else {
1358	            session_cwd
1359	        };
1360	        let err = std::process::Command::new("claude")
1361	            .arg("--resume")
1362	            .arg(session_id)
1363	            .current_dir(&launch_dir)
1364	            .exec();
1365	        eprintln!("exec failed: {err}");
1366	        // exec failed — fall back to entire resume, checking out the session branch first
1367	        resume_via_entire(&launch_dir, &session_branch);
1368	    } else {
1369	        resume_via_entire(fallback_cwd, "");
1370	    }
1371	}
