1375	fn build_flat(
1376	    cards: &[Card],
1377	    term_w: usize,
1378	    collapsed: &std::collections::HashSet<usize>,
1379	    expanded_files: &std::collections::HashSet<(usize, usize)>,
1380	    diff_cache: &std::collections::HashMap<(usize, usize), Vec<String>>,
1381	) -> (Vec<(usize, String)>, Vec<Selectable>, Vec<usize>) {
1382	    let w = term_w.saturating_sub(2);
1383	    let mut flat: Vec<(usize, String)> = Vec::new();
1384	    let mut selectables: Vec<Selectable> = Vec::new();
1385	    let mut starts: Vec<usize> = Vec::new();
1386	
1387	    let agent: &str = cards.iter().find_map(|c| {
1388	        if let Card::Header { agent, .. } = c { Some(agent.as_str()) } else { None }
1389	    }).unwrap_or("");
1390	
1391	    for (card_idx, card) in cards.iter().enumerate() {
1392	        if let Card::ToolRound { parts } = card {
1393	            if collapsed.contains(&card_idx) {
1394	                let si = selectables.len();
1395	                starts.push(flat.len());
1396	                selectables.push(Selectable::Card(card_idx));
1397	                for l in render_tool_summary(parts) { flat.push((si, l)); }
1398	            } else {
1399	                let si = selectables.len();
1400	                starts.push(flat.len());
1401	                selectables.push(Selectable::ToolHeader(card_idx));
1402	                for l in render_tool_header(parts) { flat.push((si, l)); }
1403	                for (tool_idx, part) in parts.iter().enumerate() {
1404	                    let si = selectables.len();
1405	                    starts.push(flat.len());
1406	                    selectables.push(Selectable::ToolCall(card_idx, tool_idx));
1407	                    for l in render_one_tool_call(part, w) { flat.push((si, l)); }
1408	                }
1409	            }
1410	        } else if let Card::Checkpoint(cp) = card {
1411	            if collapsed.contains(&card_idx) {
1412	                let si = selectables.len();
1413	                starts.push(flat.len());
1414	                selectables.push(Selectable::Card(card_idx));
1415	                for l in render_checkpoint_collapsed(cp, term_w) { flat.push((si, l)); }
1416	            } else {
1417	                let t = crate::theme::get();
1418	                // CheckpointHeader owns: green bar + blank + stats + (if files) "Files" label
1419	                let si = selectables.len();
1420	                starts.push(flat.len());
1421	                selectables.push(Selectable::CheckpointHeader(card_idx));
1422	                flat.push((si, render_checkpoint_header(cp, true, term_w)));
1423	                flat.push((si, String::new()));
1424	                for l in render_checkpoint_stats(cp) { flat.push((si, l)); }
1425	                if !cp.files_touched.is_empty() {
1426	                    flat.push((si, format!("  \x1b[{lb}mFiles\x1b[0m", lb = t.label)));
1427	                }
1428	
1429	                // One selectable per file
1430	                let n = cp.files_touched.len();
1431	                for (file_idx, f) in cp.files_touched.iter().enumerate() {
1432	                    let fsi = selectables.len();
1433	                    starts.push(flat.len());
1434	                    selectables.push(Selectable::CheckpointFile(card_idx, file_idx));
1435	                    let is_open = expanded_files.contains(&(card_idx, file_idx));
1436	                    let arrow = if is_open { "▾" } else { "▸" };
1437	                    flat.push((fsi, format!("    {arrow} \x1b[{dm}m{f}\x1b[0m", dm = t.text_dim)));
1438	                    if is_open {
1439	                        if let Some(diff) = diff_cache.get(&(card_idx, file_idx)) {
1440	                            for dl in diff { flat.push((fsi, dl.clone())); }
1441	                        }
1442	                    }
1443	                    if file_idx + 1 == n {
1444	                        flat.push((fsi, String::new())); // blank after last file
1445	                    }
1446	                }
1447	            }
1448	        } else {
1449	            let si = selectables.len();
1450	            starts.push(flat.len());
1451	            selectables.push(Selectable::Card(card_idx));
1452	            for l in render_card(card, w, agent) { flat.push((si, l)); }
1453	        }
1454	    }
1455	
1456	    (flat, selectables, starts)
1457	}
