1459	// `Back` returns to whatever called show (the sessions list, the repo TUI, or
1460	// the CLI). `Quit` propagates a full-app exit so q from anywhere quits.
1461	enum PagerOutcome { Back, Quit, Resume, Delete, GoToSessions, GoToRepo(String) }
1462	
1463	fn pager(cards: &[Card], start_ts: Option<&str>) -> Result<PagerOutcome> {
1464	    let (term_w, term_h) = terminal::size().unwrap_or((120, 40));
1465	    let mut w = term_w as usize;
1466	    let mut h = (term_h as usize).saturating_sub(1);
1467	
1468	    let mut collapsed: std::collections::HashSet<usize> = cards.iter().enumerate()
1469	        .filter_map(|(i, c)| if matches!(c, Card::ToolRound { .. } | Card::Checkpoint(_)) { Some(i) } else { None })
1470	        .collect();
1471	
1472	    let mut expanded_files: std::collections::HashSet<(usize, usize)> = std::collections::HashSet::new();
1473	    let mut diff_cache: std::collections::HashMap<(usize, usize), Vec<String>> = std::collections::HashMap::new();
1474	
1475	    let (mut flat, mut selectables, mut starts) = build_flat(&cards, w, &collapsed, &expanded_files, &diff_cache);
1476	
1477	    let mut stdout = io::stdout();
1478	
1479	    let orig_hook = std::panic::take_hook();
1480	    std::panic::set_hook(Box::new(move |info| {
1481	        let mut out = io::stdout();
1482	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
1483	        let _ = terminal::disable_raw_mode();
1484	        orig_hook(info);
1485	    }));
1486	
1487	    terminal::enable_raw_mode()?;
1488	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
1489	
1490	    // If a target timestamp was given, jump to the first card whose ts matches.
1491	    // Fall back to the first selectable (beginning of session) if not found.
1492	    let initial_sel = start_ts.and_then(|ts| {
1493	        cards.iter().enumerate().find_map(|(ci, card)| {
1494	            let card_ts = match card {
1495	                Card::UserMsg { ts, .. } | Card::AsstMsg { ts, .. } | Card::System { ts, .. } => ts.as_str(),
1496	                _ => return None,
1497	            };
1498	            if card_ts == ts {
1499	                selectables.iter().position(|s| *s == Selectable::Card(ci))
1500	            } else {
1501	                None
1502	            }
1503	        })
1504	    }).unwrap_or(0);
1505	
1506	    let mut sel: usize = initial_sel;
1507	    let mut scroll: usize = 0;
1508	    let mut flash:  Option<&str> = None;
1509	    let mut awaiting_delete = false;
1510	
1511	    let result: Result<PagerOutcome> = loop {
1512	        let s = starts[sel];
1513	        let e = starts.get(sel + 1).copied().unwrap_or(flat.len());
1514	        if s < scroll          { scroll = s; }
1515	        else if e > scroll + h { scroll = e.saturating_sub(h); }
1516	
1517	        if let Err(err) = draw(&mut stdout, &flat, &starts, sel, scroll, h, w, selectables.len(), flash) {
1518	            break Err(anyhow::anyhow!(err));
1519	        }
1520	
1521	        match event::read() {
1522	            Err(e) => break Err(e.into()),
1523	            Ok(Event::Key(k)) => {
1524	                let prev_flash = flash.take();
1525	                match (k.code, k.modifiers) {
1526	                    (KeyCode::Char('q'), _) => break Ok(PagerOutcome::Quit),
1527	                    (KeyCode::Char('c'), KeyModifiers::CONTROL) => break Ok(PagerOutcome::Quit),
1528	                    (KeyCode::Esc | KeyCode::Left, _) => break Ok(PagerOutcome::Back),
1529	                    (KeyCode::Char('r'), _) => break Ok(PagerOutcome::Resume),
1530	                    (KeyCode::Char('d'), _) => {
1531	                        awaiting_delete = true;
1532	                        flash = Some("  Delete session? Press y to confirm, any other key to cancel  ");
1533	                        continue;
1534	                    }
1535	                    (KeyCode::Char('y'), _) if awaiting_delete => {
1536	                        break Ok(PagerOutcome::Delete);
1537	                    }
1538	
1539	                    (KeyCode::Down | KeyCode::Char('j'), _) => {
1540	                        if sel + 1 < selectables.len() { sel += 1; }
1541	                    }
1542	                    (KeyCode::Up | KeyCode::Char('k'), _) => {
1543	                        if sel > 0 { sel -= 1; }
1544	                    }
1545	                    (KeyCode::Char('g'), _) => { sel = 0; }
1546	                    (KeyCode::Char('G'), _) => { sel = selectables.len().saturating_sub(1); }
1547	
1548	                    (KeyCode::Char(']'), _) => {
1549	                        let is_cp = |s: &Selectable| match s {
1550	                            Selectable::Card(ci) => matches!(&cards[*ci], Card::Checkpoint(_)),
1551	                            Selectable::CheckpointHeader(..) => true,
1552	                            _ => false,
1553	                        };
1554	                        if let Some(i) = selectables.iter().enumerate().skip(sel + 1).find(|(_, s)| is_cp(s)).map(|(i, _)| i) {
1555	                            sel = i;
1556	                        }
1557	                    }
1558	                    (KeyCode::Char('['), _) => {
1559	                        let is_cp = |s: &Selectable| match s {
1560	                            Selectable::Card(ci) => matches!(&cards[*ci], Card::Checkpoint(_)),
1561	                            Selectable::CheckpointHeader(..) => true,
1562	                            _ => false,
1563	                        };
1564	                        if let Some(i) = selectables.iter().enumerate().take(sel).rfind(|(_, s)| is_cp(s)).map(|(i, _)| i) {
1565	                            sel = i;
1566	                        }
1567	                    }
1568	
1569	                    (KeyCode::Char('u'), _) | (KeyCode::PageUp, _) => {
1570	                        scroll = scroll.saturating_sub(h / 2);
1571	                        sel = flat[scroll].0;
1572	                    }
1573	                    (KeyCode::PageDown, _) => {
1574	                        scroll = (scroll + h / 2).min(flat.len().saturating_sub(h));
1575	                        sel = flat[scroll].0;
1576	                    }
1577	
1578	                    (KeyCode::Char('y'), _) | (KeyCode::Char('c'), _) => {
1579	                        let text = match &selectables[sel] {
1580	                            Selectable::Card(ci)             => card_text(&cards[*ci]),
1581	                            Selectable::ToolHeader(ci)       => card_text(&cards[*ci]),
1582	                            Selectable::CheckpointHeader(ci) => card_text(&cards[*ci]),
1583	                            Selectable::ToolCall(ci, ti) => {
1584	                                if let Card::ToolRound { parts } = &cards[*ci] {
1585	                                    parts.get(*ti).map_or(String::new(), tool_call_text)
1586	                                } else { String::new() }
1587	                            }
1588	                            Selectable::CheckpointFile(ci, fi) => {
1589	                                if let Card::Checkpoint(cp) = &cards[*ci] {
1590	                                    cp.files_touched.get(*fi).cloned().unwrap_or_default()
1591	                                } else { String::new() }
1592	                            }
1593	                        };
1594	                        copy_to_clipboard(&text);
1595	                        flash = Some("  ✓ copied to clipboard  ");
1596	                    }
1597	
1598	                    // Space/Right/Enter: expand ToolRound/Checkpoint, collapse via header, or navigate
1599	                    (KeyCode::Char(' ') | KeyCode::Right | KeyCode::Enter, _) => {
1600	                        let expand_action = match &selectables[sel] {
1601	                            Selectable::Card(ci) if matches!(&cards[*ci], Card::ToolRound { .. }) => {
1602	                                Some((true, *ci, false))
1603	                            }
1604	                            Selectable::Card(ci) if matches!(&cards[*ci], Card::Checkpoint(_)) => {
1605	                                Some((true, *ci, true))
1606	                            }
1607	                            Selectable::ToolHeader(ci) => Some((false, *ci, false)),
1608	                            Selectable::CheckpointHeader(ci) => Some((false, *ci, true)),
1609	                            _ => None,
1610	                        };
1611	                        if let Some((expand, card_idx, is_checkpoint)) = expand_action {
1612	                            if expand { collapsed.remove(&card_idx); } else { collapsed.insert(card_idx); }
1613	                            let (nf, ns, nst) = build_flat(cards, w, &collapsed, &expanded_files, &diff_cache);
1614	                            flat   = nf;
1615	                            starts = nst;
1616	                            sel = if expand {
1617	                                if is_checkpoint {
1618	                                    ns.iter().position(|s| *s == Selectable::CheckpointHeader(card_idx))
1619	                                } else {
1620	                                    ns.iter().position(|s| *s == Selectable::ToolHeader(card_idx))
1621	                                }
1622	                            } else {
1623	                                ns.iter().position(|s| *s == Selectable::Card(card_idx))
1624	                            }.unwrap_or_else(|| sel.min(ns.len().saturating_sub(1)));
1625	                            selectables = ns;
1626	                        } else if let Selectable::CheckpointFile(ci, fi) = &selectables[sel] {
1627	                            let key = (*ci, *fi);
1628	                            if expanded_files.contains(&key) {
1629	                                expanded_files.remove(&key);
1630	                            } else {
1631	                                if !diff_cache.contains_key(&key) {
1632	                                    if let Card::Checkpoint(cp) = &cards[*ci] {
1633	                                        if let Some(f) = cp.files_touched.get(*fi) {
1634	                                            diff_cache.insert(key, fetch_file_diff(&cp.commit_sha, &cp.repo_dir, f));
1635	                                        }
1636	                                    }
1637	                                }
1638	                                expanded_files.insert(key);
1639	                            }
1640	                            let target = Selectable::CheckpointFile(*ci, *fi);
1641	                            let (nf, ns, nst) = build_flat(cards, w, &collapsed, &expanded_files, &diff_cache);
1642	                            flat = nf; starts = nst;
1643	                            sel = ns.iter().position(|s| *s == target)
1644	                                .unwrap_or_else(|| sel.min(ns.len().saturating_sub(1)));
1645	                            selectables = ns;
1646	                        } else if let Selectable::Card(ci) = &selectables[sel] {
1647	                            match &cards[*ci] {
1648	                                Card::RepoLink { dir, .. } => {
1649	                                    break Ok(PagerOutcome::GoToRepo(dir.clone()));
1650	                                }
1651	                                Card::Header { .. } => {
1652	                                    break Ok(PagerOutcome::GoToSessions);
1653	                                }
1654	                                _ => { flash = prev_flash; }
1655	                            }
1656	                        } else {
1657	                            flash = prev_flash;
1658	                        }
1659	                    }
1660	
1661	                    (KeyCode::Char('/'), _) => {
1662	                        if let Some(query) = super::collect_search_query(&mut stdout, w, h) {
1663	                            if !query.trim().is_empty() {
1664	                                execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
1665	                                terminal::disable_raw_mode()?;
1666	                                super::search::run(&query, 10, false).unwrap_or(false);
1667	                                terminal::enable_raw_mode()?;
1668	                                execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
1669	                                execute!(stdout, terminal::Clear(ClearType::All))?;
1670	                            }
1671	                        }
1672	                    }
1673	
1674	                    _ => { awaiting_delete = false; flash = prev_flash; }
1675	                }
1676	            }
1677	            Ok(Event::Resize(new_w, new_h)) => {
1678	                w = new_w as usize;
1679	                h = (new_h as usize).saturating_sub(1);
1680	                let (nf, ns, nst) = build_flat(&cards, w, &collapsed, &expanded_files, &diff_cache);
1681	                flat = nf; selectables = ns; starts = nst;
1682	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
1683	            }
1684	            Ok(_) => {}
1685	        }
1686	    };
1687	
1688	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
1689	    terminal::disable_raw_mode()?;
1690	    result
1691	}
