1693	fn draw(
1694	    stdout: &mut impl Write,
1695	    flat:   &[(usize, String)],
1696	    starts: &[usize],
1697	    sel:    usize,
1698	    scroll: usize,
1699	    h:      usize,
1700	    w:      usize,
1701	    total:  usize,
1702	    flash:  Option<&str>,
1703	) -> io::Result<()> {
1704	    use crossterm::queue;
1705	    let accent = crate::theme::get().accent;
1706	
1707	    let end = (scroll + h).min(flat.len());
1708	
1709	    // Build the entire frame into one buffer; flush once to eliminate flicker.
1710	    // Use explicit cursor::MoveTo per row so embedded newlines in content can't
1711	    // shift subsequent rows into the wrong position.
1712	    let mut buf: Vec<u8> = Vec::with_capacity((w + 40) * (h + 2));
1713	
