99	pub fn run_at(session_id: &str, turn_id: Option<&str>, hit_ts: Option<&str>, hit_off: Option<u64>, checkpoint_id: Option<&str>) -> Result<bool> {
100	    let path = find_session(session_id)
101	        .with_context(|| format!("no session file found for '{session_id}'"))?;
102	
103	    let raw = std::fs::read_to_string(&path)
104	        .with_context(|| format!("cannot read {}", path.display()))?;
105	
106	    // Resolve to a timestamp for pager navigation.
107	    // Priority: raw hit_ts (directly from witchcraft metadata, same source as
108	    // the JSONL timestamp field) → uuid scan of local file → byte-offset scan
109	    // (hit_off is relative to the shadow-branch copy, so only use as a last
110	    // resort when the other two come up empty).
111	    let resolved_ts: Option<String> = hit_ts.map(str::to_string)
112	        .or_else(|| turn_id.and_then(|tid| {
113	            for line in raw.lines() {
114	                let Ok(v) = serde_json::from_str::<serde_json::Value>(line) else { continue };
115	                if v["uuid"].as_str() == Some(tid) {
116	                    return v["timestamp"].as_str().map(str::to_string);
117	                }
118	            }
119	            None
120	        }))
121	        .or_else(|| hit_off.and_then(|off| {
122	            let bytes = raw.as_bytes();
123	            if (off as usize) < bytes.len() {
124	                let slice = &bytes[off as usize..];
125	                let end = slice.iter().position(|&b| b == b'\n').unwrap_or(slice.len());
126	                std::str::from_utf8(&slice[..end]).ok()
127	                    .and_then(|line| serde_json::from_str::<serde_json::Value>(line).ok())
128	                    .and_then(|v| v["timestamp"].as_str().map(str::to_string))
129	            } else { None }
130	        }));
131	    let start_ts: Option<&str> = resolved_ts.as_deref();
132	
133	    // Look up agent name and DB-stored session_name from the gossamer DB.
134	    let uuid = path.file_stem().and_then(|s| s.to_str()).unwrap_or("");
135	    let (agent, db_session_name) = if let Ok(conn) = crate::db::connect() {
136	        conn.query_row(
137	            "SELECT agent_name, COALESCE(session_name, '') FROM sessions WHERE session_id = ?1",
138	            [uuid],
139	            |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
140	        ).unwrap_or_default()
141	    } else { (String::new(), String::new()) };
142	
143	    let mut cards = parse(&raw, &agent);
144	    if cards.is_empty() {
145	        println!("No messages found.");
146	        return Ok(false);
147	    }
148	
149	    let checkpoints = fetch_checkpoints(uuid);
150	    if !checkpoints.is_empty() {
151	        insert_checkpoints(&mut cards, checkpoints);
152	    }
153	
154	    // Title fallback chain: JSONL custom-title (already set by parse) →
155	    // DB session_name (the indexer's first-meaningful-prompt) → first user
156	    // prompt in the JSONL. Covers sessions that were never /rename'd.
157	    let mut need_prompt_fallback = false;
158	    if let Some(Card::Header { title, .. }) = cards.iter_mut().find(|c| matches!(c, Card::Header { .. })) {
159	        if title.as_deref().map_or(true, str::is_empty) {
160	            if !db_session_name.trim().is_empty() {
161	                *title = Some(db_session_name);
162	            } else {
163	                need_prompt_fallback = true;
164	            }
165	        }
166	    }
167	    if need_prompt_fallback {
168	        let first_user_text: Option<String> = cards.iter().find_map(|c| {
169	            if let Card::UserMsg { parts, .. } = c {
170	                parts.iter().find_map(|p| {
171	                    if let UserPart::Text(t) = p {
172	                        let trimmed = t.trim();
173	                        if trimmed.is_empty() { None } else { Some(trimmed.to_string()) }
174	                    } else { None }
175	                })
176	            } else { None }
177	        });
178	        if let Some(text) = first_user_text {
179	            if let Some(Card::Header { title, .. }) = cards.iter_mut().find(|c| matches!(c, Card::Header { .. })) {
180	                *title = Some(text);
181	            }
182	        }
183	    }
184	
185	    // Extract branch and cwd from the Header before cards are consumed by pager.
186	    let session_branch = cards.iter().find_map(|c| {
187	        if let Card::Header { branch, .. } = c { Some(branch.clone()) } else { None }
188	    }).unwrap_or_default();
189	    let session_cwd = cards.iter().find_map(|c| {
190	        if let Card::Header { cwd, .. } = c { Some(cwd.clone()) } else { None }
191	    }).unwrap_or_default();
192	
193	    // Attribute each user message to the checkpoint author, or fall back to
194	    // git config user.name for sessions not yet indexed from the checkpoint branch.
195	    let authors = fetch_authors(uuid);
196	    if !authors.is_empty() {
197	        for card in cards.iter_mut() {
198	            if let Card::UserMsg { ts, author, .. } = card {
199	                *author = attribute(&authors, ts);
200	            }
201	        }
202	    } else if let Some(name) = git_config_user(&session_cwd) {
203	        for card in cards.iter_mut() {
204	            if let Card::UserMsg { author, .. } = card {
205	                *author = Some(name.clone());
206	            }
207	        }
208	    }
209	
210	    // Look up the repo that owns this session's cwd and prepend a RepoLink card.
211	    if let Ok(conn) = crate::db::connect() {
212	        if let Ok((repo_name, repo_dir)) = conn.query_row(
213	            "SELECT name, directory FROM repositories
214	             WHERE ?1 LIKE (directory || '%')
