     let mut match_line_idx: usize = 0;
     if sub_idx > 1 {
         if let Some(prev) = bodies.get(sub_idx - 1) {
             let t = strip_user_label(prev.trim()).chars().take(220).collect::<String>();
             if !t.is_empty() {
                 excerpt_lines.push(t);
                 match_line_idx = excerpt_lines.len(); // matched line will follow
             }
         }
     }
     if let Some(matched) = bodies.get(sub_idx) {
         let t = strip_user_label(matched.trim()).chars().take(400).collect::<String>();
         if !t.is_empty() {
             match_line_idx = excerpt_lines.len();
             excerpt_lines.push(t);
         }
     }
     if sub_idx + 1 < bodies.len() {
         if let Some(next) = bodies.get(sub_idx + 1) {
             let t = strip_user_label(next.trim()).chars().take(220).collect::<String>();
             if !t.is_empty() { excerpt_lines.push(t); }
         }
     }
     ```
     - Updated draw function to show `▶` marker + brighter color on matched line, dimmer `  ` indent on context lines:
     ```rust
     let is_match_line = li == row.match_line_idx;
     let line_color = if is_match_line { t.text_primary } else { t.text_secondary };
     let match_marker = if is_match_line { "▶ " } else { "  " };
     // ... then use match_marker and line_color in format strings
     ```
     - All `SearchHit` constructors updated to include `match_line_idx: 0` (for non-log hits)
     - `build_groups`: passes `match_line_idx: hit.match_line_idx` to `GroupRow`

4. Errors and Fixes:
   - **Navigation goes to wrong message**: Root cause was `hit_off` (byte offset relative to shadow branch JSONL) being tried FIRST and returning a wrong timestamp when applied to the local file. Fixed by putting `hit_ts` first in the chain.
